{
  "name": "Foundation Manager Pro",
  "description": "A comprehensive management system for foundations featuring organizational structure visualization, member directories, constitution management, and financial tracking with AI insights."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type CouncilType = 'ADVISORY' | 'EXECUTIVE' | 'GENERAL';

export interface Member {
  id: string;
  name: string;
  phone: string;
  council: CouncilType;
  designation?: string; // Only for Executive
  joinDate: string;
}

export type TransactionType = 'INCOME' | 'EXPENSE';

export interface Transaction {
  id: string;
  date: string; // ISO string
  month: string; // Bengali or English month name
  year: number;
  amount: number;
  type: TransactionType;
  category: string; // 'Subscription', 'Donation', 'EventCost', etc.
  description?: string;
  memberId?: string; // For subscription tracking
}

export interface ConstitutionSection {
  id: string;
  title: string;
  content: string;
}

export const MONTHS = [
  'জানুয়ারি', 'ফেব্রুয়ারি', 'মার্চ', 'এপ্রিল', 'মে', 'জুন',
  'জুলাই', 'আগস্ট', 'সেপ্টেম্বর', 'অক্টোবর', 'নভেম্বর', 'ডিসেম্বর'
];

export const YEARS = [2023, 2024, 2025, 2026, 2027];

import { GoogleGenAI } from "@google/genai";

const apiKey = process.env.API_KEY || '';

// Initialize the client
let ai: GoogleGenAI | null = null;
if (apiKey) {
    ai = new GoogleGenAI({ apiKey: apiKey });
}

export const generateConstitutionContent = async (topic: string): Promise<string> => {
  if (!ai) return "API Key not configured.";

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Write a formal and professional constitution clause for a non-profit foundation regarding: "${topic}". 
      Write it in Bengali. Keep it concise, clear, and legalistic suitable for an organization's bylaws.`,
    });
    return response.text || "Could not generate content.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Error generating content. Please check your API key.";
  }
};

export const analyzeFinancials = async (summaryData: string): Promise<string> => {
  if (!ai) return "API Key not configured.";

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analyze the following financial summary for our foundation and provide 3 key insights or suggestions in Bengali: 
      ${summaryData}`,
    });
    return response.text || "Could not analyze data.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Error analyzing data.";
  }
};

import React, { useState } from 'react';
import { FileText, Save, Download, Sparkles, Printer } from 'lucide-react';
import { generateConstitutionContent } from '../services/geminiService';
import { ConstitutionSection } from '../types';

interface Props {
  logoUrl: string | null;
}

export const Constitution: React.FC<Props> = ({ logoUrl }) => {
  const [sections, setSections] = useState<ConstitutionSection[]>([
    { id: '1', title: 'নামকরণ ও কার্যালয়', content: 'এই সংগঠনের নাম হইবে "আপন ফাউন্ডেশন"। এর প্রধান কার্যালয় ঢাকা, বাংলাদেশে অবস্থিত হইবে।' },
    { id: '2', title: 'লক্ষ্য ও উদ্দেশ্য', content: 'দরিদ্র ও অসহায় মানুষের সেবা করা। শিক্ষা ও স্বাস্থ্যের উন্নয়ন ঘটানো।' }
  ]);
  const [isEditing, setIsEditing] = useState(false);
  const [aiPrompt, setAiPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);

  const handleAiDraft = async () => {
    if (!aiPrompt) return;
    setIsGenerating(true);
    const draft = await generateConstitutionContent(aiPrompt);
    setSections([...sections, { id: Date.now().toString(), title: aiPrompt, content: draft }]);
    setAiPrompt('');
    setIsGenerating(false);
  };

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center no-print">
        <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
          <FileText className="text-blue-600" /> গঠনতন্ত্র ও নীতিমালা
        </h2>
        <div className="flex gap-2">
          <button 
            onClick={() => setIsEditing(!isEditing)}
            className="px-4 py-2 bg-slate-200 text-slate-700 rounded-lg hover:bg-slate-300 font-medium"
          >
            {isEditing ? 'প্রিভিউ দেখুন' : 'এডিট করুন'}
          </button>
          <button 
            onClick={handlePrint}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-medium flex items-center gap-2"
          >
            <Printer size={18} /> প্রিন্ট / PDF
          </button>
        </div>
      </div>

      {isEditing && (
        <div className="bg-white p-6 rounded-xl shadow border border-slate-200 no-print">
          <h3 className="font-semibold text-lg mb-4">নতুন অনুচ্ছেদ যোগ করুন</h3>
          <div className="flex gap-2 mb-4">
            <input 
              type="text" 
              value={aiPrompt}
              onChange={(e) => setAiPrompt(e.target.value)}
              placeholder="যেমন: সদস্যপদ বাতিল সংক্রান্ত নীতিমালা..."
              className="flex-1 p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
            />
            <button 
              onClick={handleAiDraft}
              disabled={isGenerating}
              className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 flex items-center gap-2 disabled:opacity-50"
            >
              <Sparkles size={18} /> {isGenerating ? 'লিখছে...' : 'Gemini দিয়ে লিখুন'}
            </button>
          </div>

          <div className="space-y-4 max-h-96 overflow-y-auto">
            {sections.map((section, idx) => (
              <div key={section.id} className="p-4 border border-slate-200 rounded-lg bg-slate-50">
                <input 
                  value={section.title}
                  onChange={(e) => {
                    const newSections = [...sections];
                    newSections[idx].title = e.target.value;
                    setSections(newSections);
                  }}
                  className="w-full font-bold mb-2 p-1 bg-transparent border-b border-transparent focus:border-slate-300 outline-none"
                />
                <textarea 
                  value={section.content}
                  onChange={(e) => {
                    const newSections = [...sections];
                    newSections[idx].content = e.target.value;
                    setSections(newSections);
                  }}
                  className="w-full h-24 p-1 bg-transparent resize-none border border-transparent focus:border-slate-300 rounded outline-none"
                />
              </div>
            ))}
          </div>
        </div>
      )}

      {/* A4 Preview Container */}
      <div className="flex justify-center bg-slate-200 p-8 overflow-auto print:bg-white print:p-0">
        <div id="constitution-doc" className="a4-page bg-white w-[210mm] min-h-[297mm] p-[25mm] shadow-xl text-slate-900">
          <div className="text-center mb-12 border-b-2 border-slate-800 pb-8">
            {logoUrl && <img src={logoUrl} alt="Logo" className="h-24 mx-auto mb-4" />}
            <h1 className="text-3xl font-bold mb-2">আপন ফাউন্ডেশন</h1>
            <h2 className="text-xl font-medium text-slate-600">গঠনতন্ত্র ও নীতিমালা</h2>
            <p className="text-sm text-slate-500 mt-2">স্থাপিত: ২০২৪ | রেজি: ১২৩৪৫</p>
          </div>

          <div className="space-y-8">
            {sections.map((section, index) => (
              <div key={section.id}>
                <h3 className="text-lg font-bold mb-2">অনুচ্ছেদ {index + 1}: {section.title}</h3>
                <p className="text-justify leading-relaxed text-slate-700 whitespace-pre-wrap">
                  {section.content}
                </p>
              </div>
            ))}
          </div>

          <div className="mt-24 pt-8 border-t border-slate-300 flex justify-between text-sm font-semibold">
            <div>সভাপতি</div>
            <div>সাধারণ সম্পাদক</div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Search, Plus, User, Trash2 } from 'lucide-react';
import { Member, CouncilType } from '../types';

interface Props {
  members: Member[];
  onAddMember: (member: Member) => void;
  onDeleteMember: (id: string) => void;
}

export const MemberDirectory: React.FC<Props> = ({ members, onAddMember, onDeleteMember }) => {
  const [activeTab, setActiveTab] = useState<CouncilType>('GENERAL');
  const [searchTerm, setSearchTerm] = useState('');
  const [showAddForm, setShowAddForm] = useState(false);
  const [newMember, setNewMember] = useState<Partial<Member>>({ council: 'GENERAL', joinDate: new Date().toISOString().split('T')[0] });

  const filteredMembers = useMemo(() => {
    return members.filter(m => 
      m.council === activeTab && 
      (m.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
       m.phone.includes(searchTerm))
    );
  }, [members, activeTab, searchTerm]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newMember.name && newMember.phone) {
      onAddMember({
        id: Date.now().toString(),
        name: newMember.name,
        phone: newMember.phone,
        council: newMember.council as CouncilType,
        designation: newMember.designation,
        joinDate: newMember.joinDate || new Date().toISOString().split('T')[0]
      });
      setShowAddForm(false);
      setNewMember({ council: activeTab, joinDate: new Date().toISOString().split('T')[0] });
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
      <div className="p-6 border-b border-slate-200 flex flex-col md:flex-row md:items-center justify-between gap-4">
        <h2 className="text-xl font-bold text-slate-800">সদস্য তালিকা</h2>

        <div className="flex items-center gap-2 bg-slate-100 px-3 py-2 rounded-lg w-full md:w-64">
          <Search size={18} className="text-slate-400" />
          <input 
            type="text"
            placeholder="নাম বা ফোন নম্বর খুঁজুন..."
            className="bg-transparent border-none outline-none text-sm w-full"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <button 
          onClick={() => setShowAddForm(true)}
          className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 flex items-center gap-2 text-sm font-medium whitespace-nowrap"
        >
          <Plus size={18} /> নতুন সদস্য
        </button>
      </div>

      <div className="flex border-b border-slate-200">
        {(['GENERAL', 'EXECUTIVE', 'ADVISORY'] as CouncilType[]).map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`flex-1 py-3 text-sm font-medium border-b-2 transition-colors ${
              activeTab === tab 
                ? 'border-blue-600 text-blue-600 bg-blue-50' 
                : 'border-transparent text-slate-500 hover:text-slate-700'
            }`}
          >
            {tab === 'GENERAL' && 'সাধারণ পরিষদ'}
            {tab === 'EXECUTIVE' && 'নির্বাহী পরিষদ'}
            {tab === 'ADVISORY' && 'উপদেষ্টা পরিষদ'}
          </button>
        ))}
      </div>

      <div className="p-6">
        {showAddForm && (
          <div className="mb-8 bg-slate-50 p-6 rounded-xl border border-slate-200 animate-fade-in">
            <h3 className="font-bold mb-4">নতুন সদস্য যোগ করুন</h3>
            <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <input 
                placeholder="নাম" 
                className="p-2 border rounded" 
                value={newMember.name || ''} 
                onChange={e => setNewMember({...newMember, name: e.target.value})}
                required
              />
              <input 
                placeholder="ফোন নম্বর" 
                className="p-2 border rounded" 
                value={newMember.phone || ''} 
                onChange={e => setNewMember({...newMember, phone: e.target.value})}
                required
              />
              <select 
                className="p-2 border rounded"
                value={newMember.council}
                onChange={e => setNewMember({...newMember, council: e.target.value as CouncilType})}
              >
                <option value="GENERAL">সাধারণ পরিষদ</option>
                <option value="EXECUTIVE">নির্বাহী পরিষদ</option>
                <option value="ADVISORY">উপদেষ্টা পরিষদ</option>
              </select>
              {newMember.council === 'EXECUTIVE' && (
                <input 
                  placeholder="পদবী (যেমন: সভাপতি)" 
                  className="p-2 border rounded" 
                  value={newMember.designation || ''} 
                  onChange={e => setNewMember({...newMember, designation: e.target.value})}
                />
              )}
              <div className="col-span-1 md:col-span-2 flex justify-end gap-2 mt-2">
                <button type="button" onClick={() => setShowAddForm(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-200 rounded">বাতিল</button>
                <button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700">সংরক্ষণ করুন</button>
              </div>
            </form>
          </div>
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {filteredMembers.map(member => (
            <div key={member.id} className="flex items-start gap-4 p-4 border border-slate-200 rounded-lg hover:shadow-md transition-shadow bg-white group">
              <div className="w-12 h-12 bg-slate-100 rounded-full flex items-center justify-center text-slate-400">
                <User size={24} />
              </div>
              <div className="flex-1">
                <h3 className="font-bold text-slate-800">{member.name}</h3>
                {member.council === 'EXECUTIVE' && (
                  <span className="text-xs bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full font-medium">
                    {member.designation || 'সদস্য'}
                  </span>
                )}
                <p className="text-sm text-slate-500 mt-1">{member.phone}</p>
                <p className="text-xs text-slate-400 mt-2">যোগদান: {member.joinDate}</p>
              </div>
              <button 
                onClick={() => onDeleteMember(member.id)}
                className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
              >
                <Trash2 size={16} />
              </button>
            </div>
          ))}
          {filteredMembers.length === 0 && (
            <div className="col-span-full text-center py-12 text-slate-400">
              কোন সদস্য পাওয়া যায়নি
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { Plus, Download, Filter, Sparkles } from 'lucide-react';
import { Transaction, Member, MONTHS, YEARS, TransactionType } from '../types';
import { analyzeFinancials } from '../services/geminiService';

interface Props {
  transactions: Transaction[];
  members: Member[];
  onAddTransaction: (t: Transaction) => void;
  logoUrl: string | null;
}

const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884d8'];

export const FinanceManager: React.FC<Props> = ({ transactions, members, onAddTransaction, logoUrl }) => {
  const [activeTab, setActiveTab] = useState<'OVERVIEW' | 'INCOME' | 'EXPENSE'>('OVERVIEW');
  const [filterMonth, setFilterMonth] = useState<string>('all');
  const [filterYear, setFilterYear] = useState<number>(new Date().getFullYear());
  const [showForm, setShowForm] = useState(false);

  // New Transaction Form State
  const [newTx, setNewTx] = useState<Partial<Transaction>>({
    type: 'INCOME',
    year: new Date().getFullYear(),
    month: MONTHS[new Date().getMonth()],
    date: new Date().toISOString().split('T')[0]
  });

  const [aiAnalysis, setAiAnalysis] = useState<string>('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // Filter Logic
  const filteredData = useMemo(() => {
    return transactions.filter(t => {
      const matchYear = t.year === filterYear;
      const matchMonth = filterMonth === 'all' || t.month === filterMonth;
      return matchYear && matchMonth;
    });
  }, [transactions, filterYear, filterMonth]);

  // Aggregates
  const stats = useMemo(() => {
    const income = filteredData.filter(t => t.type === 'INCOME').reduce((acc, curr) => acc + curr.amount, 0);
    const expense = filteredData.filter(t => t.type === 'EXPENSE').reduce((acc, curr) => acc + curr.amount, 0);
    return { income, expense, balance: income - expense };
  }, [filteredData]);

  const chartData = useMemo(() => {
    // Group by month for Bar Chart
    const data = MONTHS.map(month => {
      const txs = transactions.filter(t => t.year === filterYear && t.month === month);
      return {
        name: month,
        আয়: txs.filter(t => t.type === 'INCOME').reduce((a, c) => a + c.amount, 0),
        ব্যয়: txs.filter(t => t.type === 'EXPENSE').reduce((a, c) => a + c.amount, 0),
      };
    });
    return data;
  }, [transactions, filterYear]);

  const pieData = useMemo(() => {
    // Group by category for current filter
    const grouped: Record<string, number> = {};
    filteredData.forEach(t => {
      if (t.type === 'EXPENSE') {
        grouped[t.category] = (grouped[t.category] || 0) + t.amount;
      }
    });
    return Object.entries(grouped).map(([name, value]) => ({ name, value }));
  }, [filteredData]);

  const handleAiAnalyze = async () => {
    setIsAnalyzing(true);
    const summary = `Year: ${filterYear}, Month: ${filterMonth}. Total Income: ${stats.income}, Total Expense: ${stats.expense}. Top Expenses: ${JSON.stringify(pieData.slice(0, 3))}`;
    const result = await analyzeFinancials(summary);
    setAiAnalysis(result);
    setIsAnalyzing(false);
  };

  const handlePrint = () => window.print();

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newTx.amount && newTx.category) {
      onAddTransaction({
        id: Date.now().toString(),
        type: newTx.type as TransactionType,
        amount: Number(newTx.amount),
        category: newTx.category,
        date: newTx.date!,
        month: newTx.month!,
        year: Number(newTx.year),
        memberId: newTx.memberId,
        description: newTx.description
      });
      setShowForm(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 no-print">
        <h2 className="text-2xl font-bold text-slate-800">আর্থিক ব্যবস্থাপনা</h2>

        <div className="flex flex-wrap gap-2">
           <select 
             className="border p-2 rounded-lg bg-white"
             value={filterYear}
             onChange={e => setFilterYear(Number(e.target.value))}
           >
             {YEARS.map(y => <option key={y} value={y}>{y}</option>)}
           </select>
           <select 
             className="border p-2 rounded-lg bg-white"
             value={filterMonth}
             onChange={e => setFilterMonth(e.target.value)}
           >
             <option value="all">পুরো বছর</option>
             {MONTHS.map(m => <option key={m} value={m}>{m}</option>)}
           </select>

           <button 
             onClick={() => setShowForm(true)}
             className="bg-emerald-600 text-white px-4 py-2 rounded-lg hover:bg-emerald-700 flex items-center gap-2"
           >
             <Plus size={18} /> এন্ট্রি যোগ করুন
           </button>
           <button 
             onClick={handlePrint}
             className="bg-slate-800 text-white px-4 py-2 rounded-lg hover:bg-slate-900 flex items-center gap-2"
           >
             <Download size={18} /> রিপোর্ট প্রিন্ট
           </button>
        </div>
      </div>

      {/* Overview Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 no-print">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-emerald-100">
          <p className="text-sm text-slate-500 mb-1">মোট আয় ({filterYear})</p>
          <h3 className="text-2xl font-bold text-emerald-600">৳ {stats.income.toLocaleString()}</h3>
        </div>
        <div className="bg-white p-6 rounded-xl shadow-sm border border-red-100">
          <p className="text-sm text-slate-500 mb-1">মোট ব্যয় ({filterYear})</p>
          <h3 className="text-2xl font-bold text-red-600">৳ {stats.expense.toLocaleString()}</h3>
        </div>
        <div className="bg-white p-6 rounded-xl shadow-sm border border-blue-100">
          <p className="text-sm text-slate-500 mb-1">বর্তমান তহবিল</p>
          <h3 className="text-2xl font-bold text-blue-600">৳ {stats.balance.toLocaleString()}</h3>
        </div>
      </div>

      {/* Entry Form */}
      {showForm && (
        <div className="bg-slate-50 p-6 rounded-xl border border-slate-200 animate-fade-in no-print">
          <h3 className="font-bold mb-4">নতুন লেনদেন যোগ করুন</h3>
          <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-3 gap-4">
             <div>
               <label className="block text-sm mb-1">ধরন</label>
               <select 
                 className="w-full p-2 border rounded"
                 value={newTx.type}
                 onChange={e => setNewTx({...newTx, type: e.target.value as TransactionType})}
               >
                 <option value="INCOME">আয় (Income)</option>
                 <option value="EXPENSE">ব্যয় (Expense)</option>
               </select>
             </div>

             {newTx.type === 'INCOME' && (
               <div>
