import React, { useState } from 'react';
import { FileText, Sparkles, Printer } from 'lucide-react';
import { generateConstitutionContent } from '../services/geminiService';
import { ConstitutionSection } from '../types';

interface Props {
  logoUrl: string | null;
  sections: ConstitutionSection[];
  onUpdateSections: (sections: ConstitutionSection[]) => void;
}

export const Constitution: React.FC<Props> = ({ logoUrl, sections, onUpdateSections }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [aiPrompt, setAiPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);

  const handleAiDraft = async () => {
    if (!aiPrompt) return;
    setIsGenerating(true);
    const draft = await generateConstitutionContent(aiPrompt);
    onUpdateSections([...sections, { id: Date.now().toString(), title: aiPrompt, content: draft }]);
    setAiPrompt('');
    setIsGenerating(false);
  };

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center no-print">
        <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
          <FileText className="text-blue-600" /> গঠনতন্ত্র ও নীতিমালা
        </h2>
        <div className="flex gap-2">
          <button 
            onClick={() => setIsEditing(!isEditing)}
            className="px-4 py-2 bg-slate-200 text-slate-700 rounded-lg hover:bg-slate-300 font-medium"
          >
            {isEditing ? 'প্রিভিউ দেখুন' : 'এডিট করুন'}
          </button>
          <button 
            onClick={handlePrint}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-medium flex items-center gap-2"
          >
            <Printer size={18} /> প্রিন্ট / PDF
          </button>
        </div>
      </div>

      {isEditing && (
        <div className="bg-white p-6 rounded-xl shadow border border-slate-200 no-print">
          <h3 className="font-semibold text-lg mb-4">নতুন অনুচ্ছেদ যোগ করুন</h3>
          <div className="flex gap-2 mb-4">
            <input 
              type="text" 
              value={aiPrompt}
              onChange={(e) => setAiPrompt(e.target.value)}
              placeholder="যেমন: সদস্যপদ বাতিল সংক্রান্ত নীতিমালা..."
              className="flex-1 p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
            />
            <button 
              onClick={handleAiDraft}
              disabled={isGenerating}
              className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 flex items-center gap-2 disabled:opacity-50"
            >
              <Sparkles size={18} /> {isGenerating ? 'লিখছে...' : 'Gemini দিয়ে লিখুন'}
            </button>
          </div>

          <div className="space-y-4 max-h-96 overflow-y-auto">
            {sections.map((section, idx) => (
              <div key={section.id} className="p-4 border border-slate-200 rounded-lg bg-slate-50">
                <input 
                  value={section.title}
                  onChange={(e) => {
                    const newSections = [...sections];
                    newSections[idx].title = e.target.value;
                    onUpdateSections(newSections);
                  }}
                  className="w-full font-bold mb-2 p-1 bg-transparent border-b border-transparent focus:border-slate-300 outline-none"
                />
                <textarea 
                  value={section.content}
                  onChange={(e) => {
                    const newSections = [...sections];
                    newSections[idx].content = e.target.value;
                    onUpdateSections(newSections);
                  }}
                  className="w-full h-24 p-1 bg-transparent resize-none border border-transparent focus:border-slate-300 rounded outline-none"
                />
              </div>
            ))}
          </div>
        </div>
      )}

      {/* A4 Preview Container */}
      <div className="flex justify-center bg-slate-200 p-8 overflow-auto print:bg-white print:p-0">
        <div id="constitution-doc" className="a4-page bg-white w-[210mm] min-h-[297mm] p-[25mm] shadow-xl text-slate-900">
          <div className="text-center mb-12 border-b-2 border-slate-800 pb-8">
            {logoUrl && <img src={logoUrl} alt="Logo" className="h-24 mx-auto mb-4" />}
            <h1 className="text-3xl font-bold mb-2">আপন ফাউন্ডেশন</h1>
            <h2 className="text-xl font-medium text-slate-600">গঠনতন্ত্র ও নীতিমালা</h2>
            <p className="text-sm text-slate-500 mt-2">স্থাপিত: ২০২৪ | রেজি: ১২৩৪৫</p>
          </div>

          <div className="space-y-8">
            {sections.map((section, index) => (
              <div key={section.id}>
                <h3 className="text-lg font-bold mb-2">অনুচ্ছেদ {index + 1}: {section.title}</h3>
                <p className="text-justify leading-relaxed text-slate-700 whitespace-pre-wrap">
                  {section.content}
                </p>
              </div>
            ))}
          </div>

          <div className="mt-24 pt-8 border-t border-slate-300 flex justify-between text-sm font-semibold">
            <div>সভাপতি</div>
            <div>সাধারণ সম্পাদক</div>
          </div>
        </div>
      </div>
    </div>
  );
};

