              className="w-full p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-orange-500"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">তারিখ</label>
            <input 
              type="date" 
              value={date}
              onChange={e => setDate(e.target.value)}
              className="w-full p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-orange-500"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">বিষয়</label>
            <input 
              type="text" 
              value={subject}
              onChange={e => setSubject(e.target.value)}
              placeholder="যেমন: মাসিক সাধারণ সভা"
              className="w-full p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-orange-500"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">নোটিশের বিবরণ</label>
            <textarea 
              value={body}
              onChange={e => setBody(e.target.value)}
              rows={6}
              placeholder="এখানে বিস্তারিত লিখুন..."
              className="w-full p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-orange-500"
            />
          </div>

          <div className="flex gap-2 pt-4">
            <button 
              onClick={() => setIsEditing(false)}
              className="flex-1 bg-slate-800 text-white py-2 rounded-lg hover:bg-slate-900 font-medium"
            >
              প্রিভিউ
            </button>
            <button 
              onClick={handlePrint}
              className="flex-1 bg-blue-600 text-white py-2 rounded-lg hover:bg-blue-700 font-medium flex items-center justify-center gap-2"
            >
              <Printer size={18} /> প্রিন্ট
            </button>
          </div>
        </div>

        {/* WhatsApp Suggestion List */}
        <div className="mt-8 pt-8 border-t border-slate-200">
           <h3 className="font-bold text-slate-700 mb-4 flex items-center gap-2">
             <Share2 size={18} className="text-green-600" /> হোয়াটসঅ্যাপে পাঠান
           </h3>
           <div className="max-h-60 overflow-y-auto space-y-2">
             {members.map(member => (
               <div key={member.id} className="flex justify-between items-center p-2 bg-slate-50 rounded border border-slate-100">
                 <div>
                   <p className="text-sm font-medium text-slate-800">{member.name}</p>
                   <p className="text-xs text-slate-500">{member.designation || member.council}</p>
                 </div>
                 <a 
                   href={getWhatsAppLink(member.phone)}
                   target="_blank"
                   rel="noopener noreferrer"
                   className="p-2 bg-green-100 text-green-700 rounded-full hover:bg-green-200 transition-colors"
                   title="Send via WhatsApp"
                 >
                   <Send size={14} />
                 </a>
               </div>
             ))}
           </div>
        </div>
      </div>

      {/* A4 Preview Area - Using new CSS classes */}
      <div className="lg:col-span-2 order-1 lg:order-2">
        <div className="a4-wrapper">
          <div className="a4-paper flex flex-col relative">

            {/* Watermark in center of page */}
            {logoUrl && (
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-0 overflow-hidden">
                <img 
                  src={logoUrl} 
                  alt="Watermark" 
                  className="w-[500px] opacity-[0.06] grayscale" 
                />
              </div>
            )}

            {/* Reusable Header */}
            <DocumentHeader logoUrl={logoUrl} />

            {/* Notice Body */}
            <div className="relative z-10 flex-1">
               <div className="flex justify-between items-center mb-8 font-medium text-slate-600 text-base">
                 <span>স্মারক নং: {refNo}</span>
                 <span>তারিখ: {date}</span>
               </div>

               <div className="text-center mb-10">
                 <span className="bg-slate-800 text-white px-8 py-2 rounded-full font-bold text-lg uppercase tracking-wider">নোটিশ</span>
               </div>

               <div className="mb-8">
                 <p className="font-bold text-xl text-slate-800 underline decoration-slate-400 underline-offset-4">বিষয়: {subject}</p>
               </div>

               <div className="text-justify leading-loose text-slate-800 text-lg whitespace-pre-wrap font-serif">
                 {body || "এখানে নোটিশের বিস্তারিত বিবরণ প্রদর্শিত হবে..."}
               </div>
            </div>

            {/* Signature Area */}
            <div className="relative z-10 mt-24 flex justify-between pt-12 gap-8">
               <div className="text-center">
                 <div className="w-48 border-t border-slate-400 mb-2 mx-auto"></div>
                 <p className="font-bold text-slate-800 text-lg">সাধারণ সম্পাদক</p>
                 <p className="text-sm text-slate-600">আপন ফাউন্ডেশন</p>
               </div>
               <div className="text-center">
                 <div className="w-48 border-t border-slate-400 mb-2 mx-auto"></div>
                 <p className="font-bold text-slate-800 text-lg">সভাপতি</p>
                 <p className="text-sm text-slate-600">আপন ফাউন্ডেশন</p>
               </div>
            </div>

            {/* Footer Line */}
            <div className="relative z-10 mt-auto pt-8 border-t-2 border-slate-800 text-center text-sm text-slate-500">
               <p>ইমেইল: info@aponfoundation.org | মোবাইল: ০১৭১১-০০০০০০</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { FileText, Sparkles, Printer } from 'lucide-react';
import { generateConstitutionContent } from '../services/geminiService';
import { ConstitutionSection } from '../types';
import { DocumentHeader } from './DocumentHeader';

interface Props {
  logoUrl: string | null;
  sections: ConstitutionSection[];
  onUpdateSections: (sections: ConstitutionSection[]) => void;
}

export const Constitution: React.FC<Props> = ({ logoUrl, sections, onUpdateSections }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [aiPrompt, setAiPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);

  const handleAiDraft = async () => {
    if (!aiPrompt) return;
    setIsGenerating(true);
    const draft = await generateConstitutionContent(aiPrompt);
    onUpdateSections([...sections, { id: Date.now().toString(), title: aiPrompt, content: draft }]);
    setAiPrompt('');
    setIsGenerating(false);
  };

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="space-y-6 pb-20">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 no-print">
        <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
          <FileText className="text-blue-600" /> গঠনতন্ত্র ও নীতিমালা
        </h2>
        <div className="flex gap-2 w-full md:w-auto">
          <button 
            onClick={() => setIsEditing(!isEditing)}
            className="flex-1 md:flex-none px-4 py-2 bg-slate-200 text-slate-700 rounded-lg hover:bg-slate-300 font-medium text-sm"
          >
            {isEditing ? 'প্রিভিউ' : 'এডিট'}
          </button>
          <button 
            onClick={handlePrint}
            className="flex-1 md:flex-none px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-medium flex items-center justify-center gap-2 text-sm"
          >
            <Printer size={18} /> প্রিন্ট
          </button>
        </div>
      </div>

      {isEditing && (
        <div className="bg-white p-6 rounded-xl shadow border border-slate-200 no-print">
          <h3 className="font-semibold text-lg mb-4">নতুন অনুচ্ছেদ যোগ করুন</h3>
          <div className="flex flex-col md:flex-row gap-2 mb-4">
            <input 
              type="text" 
              value={aiPrompt}
              onChange={(e) => setAiPrompt(e.target.value)}
              placeholder="যেমন: সদস্যপদ বাতিল সংক্রান্ত নীতিমালা..."
              className="flex-1 p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
            />
            <button 
              onClick={handleAiDraft}
              disabled={isGenerating}
              className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 flex items-center justify-center gap-2 disabled:opacity-50"
            >
              <Sparkles size={18} /> {isGenerating ? 'লিখছে...' : 'Gemini'}
            </button>
          </div>

          <div className="space-y-4 max-h-96 overflow-y-auto">
            {sections.map((section, idx) => (
              <div key={section.id} className="p-4 border border-slate-200 rounded-lg bg-slate-50">
                <input 
                  value={section.title}
                  onChange={(e) => {
                    const newSections = [...sections];
                    newSections[idx].title = e.target.value;
                    onUpdateSections(newSections);
                  }}
                  className="w-full font-bold mb-2 p-1 bg-transparent border-b border-transparent focus:border-slate-300 outline-none"
                />
                <textarea 
                  value={section.content}
                  onChange={(e) => {
                    const newSections = [...sections];
                    newSections[idx].content = e.target.value;
                    onUpdateSections(newSections);
                  }}
                  className="w-full h-24 p-1 bg-transparent resize-none border border-transparent focus:border-slate-300 rounded outline-none"
                />
