              <img 
                src={logoUrl} 
                alt="Watermark" 
                className="w-[500px] opacity-[0.06] grayscale" 
              />
            </div>
          )}

          <DocumentHeader logoUrl={logoUrl} />

          <div className="space-y-8 relative z-10 flex-1">
            <div className="text-center mb-8">
               <span className="bg-slate-100 px-6 py-2 rounded border border-slate-300 font-bold text-lg">গঠনতন্ত্র ও নীতিমালা</span>
