import { jsPDF } from 'jspdf';
import html2canvas from 'html2canvas';

// Helper to access libraries from global scope (CDN)
const getHtml2Canvas = () => (window as any).html2canvas as typeof html2canvas;
const getJsPDF = () => (window as any).jspdf.jsPDF;

export const downloadAsImage = async (elementId: string, fileName: string) => {
  const element = document.getElementById(elementId);
  const html2canvas = getHtml2Canvas();

  if (!element || !html2canvas) {
    console.error("Element or html2canvas not found");
    return;
  }

  try {
    const canvas = await html2canvas(element, {
      scale: 2, // High resolution
      backgroundColor: '#ffffff',
      useCORS: true, // For images
      logging: false
    });

    const link = document.createElement('a');
    link.download = `${fileName}.png`;
    link.href = canvas.toDataURL('image/png');
    link.click();
  } catch (err) {
    console.error("Image download failed", err);
    alert("ইমেজ ডাউনলোড করতে সমস্যা হয়েছে।");
  }
};

export const downloadAsPDF = async (elementId: string, fileName: string) => {
  const element = document.getElementById(elementId);
  const html2canvas = getHtml2Canvas();
  const JsPDF = getJsPDF();

  if (!element || !html2canvas || !JsPDF) {
    console.error("Element or libraries not found");
    return;
  }

  try {
    // 1. Capture the element as a high-res canvas
    const canvas = await html2canvas(element, {
      scale: 2,
      backgroundColor: '#ffffff',
      useCORS: true,
      logging: false
    });

    const imgData = canvas.toDataURL('image/png');

    // A4 Size calculations (in mm)
    const pdfWidth = 210;
    const pdfHeight = 297;

    // Create PDF
    const pdf = new JsPDF('p', 'mm', 'a4');

    // Calculate aspect ratio to fit width
    const imgProps = pdf.getImageProperties(imgData);
    const pdfImgHeight = (imgProps.height * pdfWidth) / imgProps.width;

    // Add image to PDF
    pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfImgHeight);

    // If content is longer than one page (basic implementation - scales to fit or cuts off)
    // For strict A4 styled divs, scaling to fit width is usually sufficient for single page reports.

    pdf.save(`${fileName}.pdf`);

  } catch (err) {
    console.error("PDF download failed", err);
    alert("পিডিএফ ডাউনলোড করতে সমস্যা হয়েছে।");
  }
};

