import React, { useState } from 'react';
import { FileText, Sparkles, Printer, Image as ImageIcon, FileDown, Edit3, ArrowRight } from 'lucide-react';
import { generateConstitutionContent } from '../services/geminiService';
import { ConstitutionSection } from '../types';
import { DocumentHeader } from './DocumentHeader';
import { downloadAsImage, downloadAsPDF } from '../utils/downloadUtils';

interface Props {
  logoUrl: string | null;
  sections: ConstitutionSection[];
  onUpdateSections: (sections: ConstitutionSection[]) => void;
}

export const Constitution: React.FC<Props> = ({ logoUrl, sections, onUpdateSections }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [aiPrompt, setAiPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);

  const handleAiDraft = async () => {
    if (!aiPrompt) return;
    setIsGenerating(true);
    const draft = await generateConstitutionContent(aiPrompt);
    onUpdateSections([...sections, { id: Date.now().toString(), title: aiPrompt, content: draft }]);
    setAiPrompt('');
    setIsGenerating(false);
  };

  const handlePrint = () => {
    window.print();
  };

  // Helper function to render text with specific formatting for Dhara/Upodhara
  const renderStyledContent = (content: string) => {
    return content.split('\n').map((line, i) => {
      const trimmed = line.trim();

      // Detection for "ধারা" (Article)
      if (trimmed.startsWith('ধারা')) {
        return (
          <div key={i} className="mt-6 mb-3 p-3 bg-emerald-50 border-l-4 border-emerald-600 rounded-r-lg shadow-sm">
            <span className="text-emerald-900 font-bold text-lg block">{line}</span>
          </div>
        );
      }

      // Detection for "উপধারা" (Sub-article)
      if (trimmed.startsWith('উপধারা')) {
        return (
          <div key={i} className="mt-2 mb-2 ml-4 pl-3 border-l-2 border-slate-300">
            <span className="text-indigo-700 font-semibold">{line}</span>
          </div>
        );
      }

      // Detection for Bullet Points
      if (trimmed.startsWith('•') || trimmed.startsWith('*') || trimmed.startsWith('-')) {
         const text = trimmed.substring(1).trim();
         return (
            <div key={i} className="flex gap-2 ml-6 mb-2 items-start">
               <div className="mt-1.5 min-w-[6px] h-[6px] rounded-full bg-slate-600"></div>
               <p className="text-justify leading-relaxed text-slate-700 font-serif text-[15px]">{text}</p>
            </div>
         )
      }

      // Empty lines
      if (trimmed === '') return <br key={i} />;

      // Standard Text
      return (
        <p key={i} className="text-justify leading-relaxed text-slate-700 ml-1 mb-1 font-serif text-[15px]">
          {line}
        </p>
      );
    });
  };

  return (
    <div className="space-y-6 pb-20">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 no-print bg-white p-4 rounded-xl shadow-sm border border-slate-200">
        <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
          <FileText className="text-blue-600" /> গঠনতন্ত্র ও নীতিমালা
        </h2>
        <div className="flex flex-wrap gap-2 w-full md:w-auto">
          <button 
            onClick={() => setIsEditing(!isEditing)}
            className={`flex-1 md:flex-none px-4 py-2 rounded-lg font-medium text-sm border flex items-center gap-2 transition-colors ${isEditing ? 'bg-blue-600 text-white border-blue-700' : 'bg-slate-100 text-slate-700 border-slate-300 hover:bg-slate-200'}`}
          >
            <Edit3 size={16} /> {isEditing ? 'প্রিভিউ দেখুন' : 'এডিট করুন'}
          </button>

          <div className="h-8 w-[1px] bg-slate-300 mx-1 hidden md:block"></div>

          <button 
            onClick={() => downloadAsImage('constitution-doc', 'Constitution_Page')}
            className="flex-1 md:flex-none px-4 py-2 bg-emerald-50 text-emerald-700 border border-emerald-200 rounded-lg hover:bg-emerald-100 font-medium flex items-center justify-center gap-2 text-sm"
            title="ছবি হিসেবে ডাউনলোড করুন"
          >
            <ImageIcon size={18} /> ছবি
          </button>
          <button 
            onClick={() => downloadAsPDF('constitution-doc', 'Constitution_Full')}
            className="flex-1 md:flex-none px-4 py-2 bg-rose-50 text-rose-700 border border-rose-200 rounded-lg hover:bg-rose-100 font-medium flex items-center justify-center gap-2 text-sm"
            title="পিডিএফ হিসেবে ডাউনলোড করুন"
          >
            <FileDown size={18} /> পিডিএফ
          </button>
          <button 
            onClick={handlePrint}
            className="flex-1 md:flex-none px-4 py-2 bg-slate-800 text-white rounded-lg hover:bg-slate-900 font-medium flex items-center justify-center gap-2 text-sm shadow-sm"
          >
            <Printer size={18} /> প্রিন্ট
          </button>
        </div>
      </div>

      {isEditing && (
        <div className="bg-white p-6 rounded-xl shadow border border-slate-200 no-print animate-fade-in">
          <h3 className="font-semibold text-lg mb-4 text-slate-800 border-b pb-2">নতুন অনুচ্ছেদ যোগ বা পরিবর্তন করুন</h3>

          {/* AI Generation Box */}
          <div className="flex flex-col md:flex-row gap-2 mb-8 bg-purple-50 p-4 rounded-lg border border-purple-100">
            <div className="flex-1">
               <label className="text-xs font-bold text-purple-700 uppercase mb-1 block">AI এর মাধ্যমে লিখুন</label>
               <input 
                type="text" 
                value={aiPrompt}
                onChange={(e) => setAiPrompt(e.target.value)}
                placeholder="যেমন: সদস্যপদ বাতিল সংক্রান্ত নীতিমালা..."
                className="w-full p-2 border border-purple-200 rounded-lg focus:ring-2 focus:ring-purple-500 outline-none"
              />
            </div>
            <button 
              onClick={handleAiDraft}
              disabled={isGenerating}
              className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 flex items-center justify-center gap-2 disabled:opacity-50 mt-auto h-10"
            >
              <Sparkles size={18} /> {isGenerating ? 'লিখছে...' : 'তৈরি করুন'}
            </button>
          </div>

          <div className="space-y-6">
            {sections.map((section, idx) => (
              <div key={section.id} className="p-4 border border-slate-200 rounded-xl bg-slate-50 relative group hover:border-blue-300 transition-colors">
                <div className="absolute top-4 right-4 text-xs text-slate-400 font-mono">ID: {idx + 1}</div>

                <div className="mb-3">
                  <label className="text-sm font-semibold text-slate-700 block mb-1">অধ্যায়ের নাম (Title)</label>
                  <input 
                    value={section.title}
                    onChange={(e) => {
                      const newSections = [...sections];
                      newSections[idx].title = e.target.value;
                      onUpdateSections(newSections);
                    }}
                    className="w-full font-bold p-2 bg-white border border-slate-300 rounded focus:border-blue-500 outline-none"
                    placeholder="অধ্যায়ের নাম লিখুন..."
                  />
                </div>

                <div>
                  <label className="text-sm font-semibold text-slate-700 block mb-1">বিস্তারিত (ধারা/উপধারা)</label>
                  <textarea 
                    value={section.content}
                    onChange={(e) => {
                      const newSections = [...sections];
                      newSections[idx].content = e.target.value;
                      onUpdateSections(newSections);
                    }}
                    className="w-full h-48 p-3 bg-white resize-y border border-slate-300 rounded focus:border-blue-500 outline-none font-serif text-sm leading-relaxed"
                    placeholder={`ধারা ১: ...\nউপধারা ১.১: ...`}
                  />
                  <p className="text-xs text-slate-500 mt-1">টিপস: নতুন প্যারাগ্রাফের জন্য 'ধারা' বা 'উপধারা' দিয়ে লাইন শুরু করুন।</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* A4 Preview Container - Using table structure for repeating headers in print */}
      <div className="a4-wrapper">
        <div id="constitution-doc" className="a4-paper flex flex-col relative">

          {/* Watermark in center of page */}
          {logoUrl && (
            <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-0 overflow-hidden">
              <img 
                src={logoUrl} 
                alt="Watermark" 
                className="w-[500px] opacity-[0.06] grayscale" 
              />
            </div>
          )}

          <DocumentHeader logoUrl={logoUrl} />

          <div className="relative z-10 flex-1">
            <div className="text-center mb-10">
               <span className="bg-slate-900 text-white px-10 py-2 rounded-lg border-2 border-slate-700 font-bold text-xl uppercase tracking-widest shadow-lg">গঠনতন্ত্র</span>
               <p className="mt-2 text-slate-500 text-sm">সর্বশেষ আপডেট: {new Date().toLocaleDateString('bn-BD')}</p>
            </div>

            <div className="space-y-8">
              {sections.map((section, index) => (
                <table key={section.id} className="w-full break-before-auto">
                   {/* Table Header Group repeats on new pages in print */}
                   <thead className="table-header-group">
                      <tr>
                        <td>
                          <div className="pb-4">
                            <div className="flex items-center gap-3 bg-gradient-to-r from-indigo-600 to-blue-600 text-white p-3 rounded-lg shadow-md print:bg-slate-800 print:text-black print:border-b-2 print:border-slate-500">
                               <div className="bg-white/20 w-8 h-8 flex items-center justify-center rounded-full font-bold text-sm border border-white/30">
                                 {index + 1}
                               </div>
                               <h3 className="text-lg font-bold tracking-wide">
                                  {section.title}
                               </h3>
                            </div>
                          </div>
                        </td>
                      </tr>
                   </thead>
                   <tbody>
                      <tr>
                        <td className="align-top">
                           <div className="pl-2 pr-1 pb-4">
                             {renderStyledContent(section.content)}
                           </div>
                        </td>
                      </tr>
                   </tbody>
                </table>
              ))}
            </div>
          </div>

          <div className="mt-auto pt-16 border-t-2 border-slate-800 flex justify-between text-sm font-semibold relative z-10">
            <div className="text-center w-40">
                <div className="border-b border-slate-400 mb-2"></div>
                সভাপতি
            </div>
            <div className="text-center w-40">
                <div className="border-b border-slate-400 mb-2"></div>
                সাধারণ সম্পাদক
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

