import React, { useState, useMemo } from 'react';
import { FileText, Sparkles, Image as ImageIcon, Edit3, Save, FileStack } from 'lucide-react';
import { generateConstitutionContent } from '../services/geminiService';
import { ConstitutionSection } from '../types';
import { DocumentHeader } from './DocumentHeader';
import { downloadAsImage, downloadMultipleElementsAsPDF } from '../utils/downloadUtils';

interface Props {
  logoUrl: string | null;
  sections: ConstitutionSection[];
  onUpdateSections: (sections: ConstitutionSection[]) => void;
}

// Type for a Renderable Page
interface RenderPage {
  id: string; // unique page id
  sectionId: string;
  sectionTitle: string;
  pageIndexInSection: number; // 0 for first page of section
  totalPagesInSection: number; // Will be calculated
  contentLines: string[];
  isGlobalLastPage: boolean;
}

// ESTIMATION CONSTANTS (in Pixels approximately)
// A4 Height @ 96 DPI is ~1123px. 
// Vertical Padding (Top+Bottom 1 inch each) ~ 192px.
// Header Area ~ 200px.
// Footer Area ~ 100px.
// Usable Height for Content ~ 630px - 700px depending on page type.
const MAX_CONTENT_HEIGHT = 750; 

const estimateLineHeight = (line: string): number => {
  const trimmed = line.trim();
  if (!trimmed) return 24; // Empty line gap
  if (trimmed.startsWith('ধারা')) return 90; // Large header + margins
  if (trimmed.startsWith('উপধারা')) return 50; // Subheader
  if (trimmed.startsWith('মিশন') || trimmed.startsWith('ভিশন')) return 70; // Mission/Vision Headers

  // Bullets and Paragraphs text wrapping estimation
  // Avg chars per line ~ 80-90 for font size 16px/14px in A4 width
  const charLength = trimmed.length;
  const lines = Math.ceil(charLength / 85); 
  return lines * 28 + 12; // 28px line-height + 12px margin
};

export const Constitution: React.FC<Props> = ({ logoUrl, sections, onUpdateSections }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [aiPrompt, setAiPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);

  const handleAiDraft = async () => {
    if (!aiPrompt) return;
    setIsGenerating(true);
    const draft = await generateConstitutionContent(aiPrompt);
    onUpdateSections([...sections, { id: Date.now().toString(), title: aiPrompt, content: draft }]);
    setAiPrompt('');
    setIsGenerating(false);
  };

  const handleDownloadFullPDF = () => {
    // Generate IDs based on the paginated view
    const pageIds = document.querySelectorAll('.a4-paper');
    const ids = Array.from(pageIds).map(el => el.id);
    downloadMultipleElementsAsPDF(ids, 'Apon_Foundation_Constitution_Full');
  };

  // --- PAGINATION LOGIC ---
  const pages = useMemo(() => {
    const generatedPages: RenderPage[] = [];

    sections.forEach((section, sectionIdx) => {
      const rawLines = section.content.split('\n');
      let currentHeight = 0;
      let currentLines: string[] = [];
      let pageIndex = 0;

      // Intro page usually has less space due to large header/footer
      const maxH = section.id === 'intro' ? 600 : MAX_CONTENT_HEIGHT;

      rawLines.forEach((line) => {
        const h = estimateLineHeight(line);

        if (currentHeight + h > maxH && currentLines.length > 0) {
          // Push current page
          generatedPages.push({
            id: `page-${section.id}-${pageIndex}`,
            sectionId: section.id,
            sectionTitle: section.title,
            pageIndexInSection: pageIndex,
            totalPagesInSection: 0, // Placeholder
            contentLines: currentLines,
            isGlobalLastPage: false // Placeholder
          });

          // Reset for next page
          currentLines = [];
          currentHeight = 0;
          pageIndex++;
        }

        currentLines.push(line);
        currentHeight += h;
      });

      // Push remaining lines
      if (currentLines.length > 0) {
        generatedPages.push({
          id: `page-${section.id}-${pageIndex}`,
          sectionId: section.id,
          sectionTitle: section.title,
          pageIndexInSection: pageIndex,
          totalPagesInSection: 0, // Placeholder
          contentLines: currentLines,
          isGlobalLastPage: false
        });
      }
    });

    // Post-process to set total pages and global last page
    return generatedPages.map((page, idx) => ({
      ...page,
      isGlobalLastPage: idx === generatedPages.length - 1
    }));

  }, [sections]);


  // Helper function to render text with specific formatting
  const renderStyledContent = (lines: string[], sectionId: string) => {
    // Logic to hide credits from body if it's intro (moved to footer)
    let linesToRender = lines;
    if (sectionId === 'intro') {
      const creditIndex = lines.findIndex(l => l.includes('সংকলন ও সম্পাদনায়:'));
      if (creditIndex !== -1) {
        linesToRender = lines.slice(0, creditIndex);
      }
    }

    return linesToRender.map((line, i) => {
      const trimmed = line.trim();

      // Detection for "ধারা" (Article)
      if (trimmed.startsWith('ধারা')) {
        return (
          <div key={i} className="mt-6 mb-3 p-3 bg-emerald-50 border-l-4 border-emerald-600 rounded-r-lg shadow-sm">
            <span className="text-emerald-900 font-bold text-lg block">{line}</span>
          </div>
        );
      }

      // Detection for "উপধারা" (Sub-article)
      if (trimmed.startsWith('উপধারা')) {
        return (
          <div key={i} className="mt-2 mb-2 ml-4 pl-3 border-l-2 border-slate-300">
            <span className="text-indigo-700 font-semibold">{line}</span>
          </div>
        );
      }

      // Detection for Bullet Points
      if (trimmed.startsWith('•') || trimmed.startsWith('*') || trimmed.startsWith('-')) {
         const text = trimmed.substring(1).trim();
         return (
            <div key={i} className="flex gap-2 ml-6 mb-2 items-start">
               <div className="mt-2 min-w-[6px] h-[6px] rounded-full bg-slate-600 shrink-0"></div>
               <p className="text-justify leading-relaxed text-slate-700 font-serif text-[16px]">{text}</p>
            </div>
         )
      }

      // Mission/Vision headers styling
      if (trimmed.startsWith('মিশন') || trimmed.startsWith('ভিশন')) {
          return (
             <h4 key={i} className="text-xl font-bold text-indigo-800 mt-6 mb-3 border-b-2 border-indigo-200 inline-block pb-1">
               {trimmed}
             </h4>
          )
      }

      // Empty lines
      if (trimmed === '') return <div key={i} className="h-4"></div>;

      // Standard Text
      return (
        <p key={i} className="text-justify leading-relaxed text-slate-700 mb-2 font-serif text-[16px]">
          {line}
        </p>
      );
    });
  };

  const getPageTitleHeader = (page: RenderPage) => {
    const isContinuation = page.pageIndexInSection > 0;
    const titleText = isContinuation ? `${page.sectionTitle} (চলমান...)` : page.sectionTitle;

    if (page.sectionId === 'intro' && page.pageIndexInSection === 0) {
      return (
        <div className="text-center mb-8">
           <span className="bg-slate-900 text-white px-10 py-2 rounded-lg border-2 border-slate-700 font-bold text-xl uppercase tracking-widest shadow-lg">
             ভূমিকা
           </span>
        </div>
      );
    } 

    if (page.sectionId === 'mission_vision') {
      return (
        <div className="flex items-center gap-3 bg-gradient-to-r from-orange-500 to-rose-500 text-white p-4 rounded-xl shadow-md mb-6">
           <div className="bg-white/20 p-2 rounded-lg"><Sparkles size={24} /></div>
           <h3 className="text-2xl font-bold tracking-wide">
              {titleText}
           </h3>
        </div>
      );
    }

    // Default Chapter Style
    return (
      <div className="flex items-center gap-3 bg-gradient-to-r from-indigo-600 to-blue-600 text-white p-3 rounded-lg shadow-md mb-6">
         {/* Show section number only on first page of section */}
         {!isContinuation && (
           <div className="bg-white/20 w-10 h-10 flex items-center justify-center rounded-full font-bold text-lg border border-white/30">
             #
           </div>
         )}
         <h3 className="text-xl font-bold tracking-wide">
            {titleText}
         </h3>
      </div>
    );
  };

  return (
    <div className="space-y-8 pb-20">
      {/* Controls Bar */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 no-print bg-white p-4 rounded-xl shadow-sm border border-slate-200 sticky top-0 z-50">
        <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
          <FileText className="text-blue-600" /> গঠনতন্ত্র ও নীতিমালা
        </h2>
        <div className="flex flex-wrap gap-2 w-full md:w-auto">
          <button 
            onClick={() => setIsEditing(!isEditing)}
            className={`flex-1 md:flex-none px-4 py-2 rounded-lg font-medium text-sm border flex items-center gap-2 transition-colors ${isEditing ? 'bg-blue-600 text-white border-blue-700' : 'bg-slate-100 text-slate-700 border-slate-300 hover:bg-slate-200'}`}
          >
            {isEditing ? <Save size={16} /> : <Edit3 size={16} />} {isEditing ? 'সেভ করুন' : 'এডিট করুন'}
          </button>

          <div className="h-8 w-[1px] bg-slate-300 mx-1 hidden md:block"></div>

          <button 
            onClick={handleDownloadFullPDF}
            className="flex-1 md:flex-none px-6 py-2 bg-rose-600 text-white rounded-lg hover:bg-rose-700 font-medium flex items-center justify-center gap-2 text-sm shadow-sm shadow-rose-200"
          >
            <FileStack size={18} /> সম্পূর্ণ পিডিএফ ডাউনলোড
          </button>
        </div>
      </div>

      {isEditing && (
        <div className="bg-white p-6 rounded-xl shadow border border-slate-200 no-print animate-fade-in">
          <h3 className="font-semibold text-lg mb-4 text-slate-800 border-b pb-2">অনুচ্ছেদ পরিবর্তন করুন</h3>

          {/* AI Generation Box */}
          <div className="flex flex-col md:flex-row gap-2 mb-8 bg-purple-50 p-4 rounded-lg border border-purple-100">
            <div className="flex-1">
               <label className="text-xs font-bold text-purple-700 uppercase mb-1 block">AI এর মাধ্যমে লিখুন</label>
               <input 
                type="text" 
                value={aiPrompt}
                onChange={(e) => setAiPrompt(e.target.value)}
                placeholder="যেমন: নতুন সদস্য হওয়ার শর্তাবলী..."
                className="w-full p-2 border border-purple-200 rounded-lg focus:ring-2 focus:ring-purple-500 outline-none"
              />
            </div>
            <button 
              onClick={handleAiDraft}
              disabled={isGenerating}
              className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 flex items-center justify-center gap-2 disabled:opacity-50 mt-auto h-10"
            >
              <Sparkles size={18} /> {isGenerating ? 'লিখছে...' : 'তৈরি করুন'}
            </button>
          </div>

          <div className="space-y-6">
            {sections.map((section, idx) => (
              <div key={section.id} className="p-4 border border-slate-200 rounded-xl bg-slate-50 relative group hover:border-blue-300 transition-colors">
                <div className="absolute top-4 right-4 text-xs text-slate-400 font-mono bg-white px-2 py-1 rounded border">Section {idx + 1}</div>

                <div className="mb-3">
                  <label className="text-sm font-semibold text-slate-700 block mb-1">শিরোনাম (Title)</label>
                  <input 
                    value={section.title}
                    onChange={(e) => {
                      const newSections = [...sections];
                      newSections[idx].title = e.target.value;
                      onUpdateSections(newSections);
                    }}
                    className="w-full font-bold p-2 bg-white border border-slate-300 rounded focus:border-blue-500 outline-none"
                  />
                </div>

                <div>
                  <label className="text-sm font-semibold text-slate-700 block mb-1">মূল বিষয়বস্তু</label>
                  <textarea 
                    value={section.content}
                    onChange={(e) => {
                      const newSections = [...sections];
                      newSections[idx].content = e.target.value;
                      onUpdateSections(newSections);
                    }}
                    className="w-full h-64 p-3 bg-white resize-y border border-slate-300 rounded focus:border-blue-500 outline-none font-serif text-sm leading-relaxed"
                  />
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* RENDER PAGINATED PAGES */}
      <div className="flex flex-col gap-12 items-center bg-slate-100 p-4 md:p-8">
        {pages.map((page, index) => {
          return (
            <div key={page.id} className="relative flex flex-col items-center gap-2">

              {/* Visible Toolbar Above Each Page */}
              <div className="w-full max-w-[210mm] flex justify-between items-center px-1 no-print">
                 <span className="text-sm font-bold text-slate-500 bg-white px-3 py-1 rounded-full shadow-sm border border-slate-200">
                    পৃষ্ঠা {index + 1}: {page.sectionTitle} {page.pageIndexInSection > 0 ? `(অংশ ${page.pageIndexInSection + 1})` : ''}
                 </span>
                 <button 
                    onClick={() => downloadAsImage(page.id, `Page_${index+1}_${page.sectionTitle}`)}
                    className="flex items-center gap-2 px-4 py-2 bg-emerald-100 text-emerald-800 rounded-lg hover:bg-emerald-200 border border-emerald-200 font-semibold text-sm transition-all shadow-sm"
                    title="শুধুমাত্র এই পৃষ্ঠাটি ডাউনলোড করুন"
                 >
                   <ImageIcon size={16} /> ইমেজ ডাউনলোড
                 </button>
              </div>

              {/* A4 Page Container */}
              <div 
                id={page.id} 
                className="a4-paper flex flex-col relative shadow-2xl bg-white overflow-hidden"
                style={{ height: '297mm', maxHeight: '297mm' }} // Enforce height
              >

                {/* Watermark */}
                {logoUrl && (
                  <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-0 overflow-hidden">
                    <img 
                      src={logoUrl} 
                      alt="Watermark" 
                      className="w-[500px] opacity-[0.06] grayscale" 
                    />
                  </div>
                )}

                {/* Content Container */}
                <div className="relative z-10 h-full flex flex-col">
                     {/* Header Section */}
                     <div className="w-full pb-4">
                        {/* Only show Full Document Header on First Page of Intro, or if desired on Page 1 */}
                        {page.sectionId === 'intro' && page.pageIndexInSection === 0 ? (
                           <DocumentHeader logoUrl={logoUrl} />
                        ) : (
                           // Mini Branding for other pages
                           <div className="flex items-center justify-between border-b border-slate-200 pb-2 mb-6">
                              <div className="flex items-center gap-2 opacity-50">
                                 {logoUrl && <img src={logoUrl} className="w-6 h-6 object-contain" />}
                                 <span className="text-xs font-bold uppercase tracking-wider text-slate-500">আপন ফাউন্ডেশন</span>
                              </div>
                              <span className="text-[10px] text-slate-400">পৃষ্ঠা {index + 1}</span>
                           </div>
                        )}

                        {/* Section Title Banner */}
                        {getPageTitleHeader(page)}
                     </div>

                     {/* Content Body */}
                     <div className="pl-1 pr-1 flex-1">
                        {renderStyledContent(page.contentLines, page.sectionId)}
                     </div>

                     {/* Footers */}
                     <div className="mt-auto pt-4">
                        {/* Footer for Introduction Page - Credits */}
                        {page.sectionId === 'intro' && page.pageIndexInSection === 0 && (
                            <div className="mt-4 pt-4 border-t-2 border-slate-800 flex justify-between items-end text-sm font-serif">
                               <div className="text-center">
                                   <p className="font-bold text-slate-800 text-lg mb-1">মুহাম্মদ উজ্জল মিয়া</p>
                                   <p className="text-slate-600">সংকলন ও সম্পাদনায়</p>
                               </div>
                               <div className="text-center">
                                   <p className="font-bold text-slate-800 text-lg mb-1">আব্দুল জিহাদ</p>
                                   <p className="text-slate-600">প্রধান উদ্যোক্তা ও প্রতিষ্ঠাতা উপদেষ্টা</p>
                               </div>
                            </div>
                        )}

                        {/* Approval Footer - ONLY on GLOBAL Last Page */}
                        {page.isGlobalLastPage && (
                           <div className="mt-4 pt-4 border-t border-slate-400 flex flex-col items-center justify-center">
                               <p className="text-sm font-semibold text-slate-500 mb-2">অনুমোদনক্রমে</p>
                               <div className="inline-block px-10 py-4 border-2 border-slate-800 rounded-lg text-center bg-white">
                                  <h2 className="text-xl font-bold text-slate-900 uppercase tracking-widest font-serif">সাধারণ পরিষদ</h2>
                                  <p className="text-slate-600 font-medium mt-1">২০২৫ ইংরেজি</p>
                               </div>
                           </div>
                        )}

                        {/* Minimal Spacer for regular pages */}
                        {!page.isGlobalLastPage && !(page.sectionId === 'intro' && page.pageIndexInSection === 0) && (
                           <div className="h-8 w-full border-t border-slate-100 mt-2"></div> 
                        )}
                     </div>
                </div>

              </div>

              {/* Page Number Label (Outside Paper) */}
              <div className="text-center mt-2 text-slate-400 text-xs font-mono no-print">
                 Page {index + 1} of {pages.length} (Sec: {page.sectionId})
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { FileText, Sparkles, Image as ImageIcon, Edit3, Save, FileStack, CheckCircle2, Bookmark, Star, Shield, Target } from 'lucide-react';
import { generateConstitutionContent } from '../services/geminiService';
import { ConstitutionSection } from '../types';
import { DocumentHeader } from './DocumentHeader';
import { downloadAsImage, downloadMultipleElementsAsPDF } from '../utils/downloadUtils';

interface Props {
  logoUrl: string | null;
  sections: ConstitutionSection[];
  onUpdateSections: (sections: ConstitutionSection[]) => void;
}

// Type for a Renderable Page
interface RenderPage {
  id: string; // unique page id
  sectionId: string;
  sectionTitle: string;
  pageIndexInSection: number; // 0 for first page of section
  totalPagesInSection: number; // Will be calculated
  contentLines: string[];
  isGlobalLastPage: boolean;
}

// Adjusted height for fluffier, more visual content
const MAX_CONTENT_HEIGHT = 700; 

const estimateLineHeight = (line: string): number => {
  const trimmed = line.trim();
  if (!trimmed) return 24; 
  if (trimmed.startsWith('ধারা')) return 100; // Increased for Card style
  if (trimmed.startsWith('উপধারা')) return 60; 
  if (trimmed.startsWith('মিশন') || trimmed.startsWith('ভিশন')) return 90; 

  // Bullets and Paragraphs
  const charLength = trimmed.length;
  const lines = Math.ceil(charLength / 80); // Slightly less chars per line due to padding
  return lines * 32 + 16; // Increased line-height and margin
};

export const Constitution: React.FC<Props> = ({ logoUrl, sections, onUpdateSections }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [aiPrompt, setAiPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);

  const handleAiDraft = async () => {
    if (!aiPrompt) return;
    setIsGenerating(true);
    const draft = await generateConstitutionContent(aiPrompt);
    onUpdateSections([...sections, { id: Date.now().toString(), title: aiPrompt, content: draft }]);
    setAiPrompt('');
    setIsGenerating(false);
  };

  const handleDownloadFullPDF = () => {
    const pageIds = document.querySelectorAll('.a4-paper');
    const ids = Array.from(pageIds).map(el => el.id);
    downloadMultipleElementsAsPDF(ids, 'Apon_Foundation_Constitution_Full');
  };

  // --- PAGINATION LOGIC ---
  const pages = useMemo(() => {
    const generatedPages: RenderPage[] = [];

    sections.forEach((section, sectionIdx) => {
      const rawLines = section.content.split('\n');
      let currentHeight = 0;
      let currentLines: string[] = [];
      let pageIndex = 0;

      // Intro page header adjustment
      const maxH = section.id === 'intro' ? 550 : MAX_CONTENT_HEIGHT;

      rawLines.forEach((line) => {
        const h = estimateLineHeight(line);

        if (currentHeight + h > maxH && currentLines.length > 0) {
          generatedPages.push({
            id: `page-${section.id}-${pageIndex}`,
            sectionId: section.id,
            sectionTitle: section.title,
            pageIndexInSection: pageIndex,
            totalPagesInSection: 0, 
            contentLines: currentLines,
            isGlobalLastPage: false 
          });

          currentLines = [];
          currentHeight = 0;
          pageIndex++;
        }

        currentLines.push(line);
        currentHeight += h;
      });

      if (currentLines.length > 0) {
        generatedPages.push({
          id: `page-${section.id}-${pageIndex}`,
          sectionId: section.id,
          sectionTitle: section.title,
          pageIndexInSection: pageIndex,
          totalPagesInSection: 0, 
          contentLines: currentLines,
          isGlobalLastPage: false
        });
      }
    });

    return generatedPages.map((page, idx) => ({
      ...page,
      isGlobalLastPage: idx === generatedPages.length - 1
    }));

  }, [sections]);


  // Helper function to render text with specific formatting
  const renderStyledContent = (lines: string[], sectionId: string) => {
    let linesToRender = lines;
    if (sectionId === 'intro') {
      const creditIndex = lines.findIndex(l => l.includes('সংকলন ও সম্পাদনায়:'));
      if (creditIndex !== -1) {
        linesToRender = lines.slice(0, creditIndex);
      }
    }

    return linesToRender.map((line, i) => {
      const trimmed = line.trim();

      // Detection for "ধারা" (Article) - Colorful Card Style
      if (trimmed.startsWith('ধারা')) {
        const [title, ...rest] = trimmed.split(':');
        return (
          <div key={i} className="mt-6 mb-4 relative break-inside-avoid">
            <div className="absolute left-0 top-0 bottom-0 w-1.5 bg-gradient-to-b from-blue-600 to-purple-600 rounded-l-lg"></div>
            <div className="bg-gradient-to-r from-blue-50 to-white p-4 rounded-r-lg shadow-sm border-t border-r border-b border-blue-100 flex items-center gap-3">
               <div className="bg-blue-600 text-white p-1.5 rounded-md shadow-md">
                 <Bookmark size={20} />
               </div>
               <div>
                  <span className="text-blue-900 font-extrabold text-lg mr-2">{title}:</span>
                  <span className="text-slate-800 font-bold text-lg">{rest.join(':')}</span>
               </div>
            </div>
          </div>
        );
      }

      // Detection for "উপধারা" (Sub-article) - Distinct Color
      if (trimmed.startsWith('উপধারা')) {
        const [title, ...rest] = trimmed.split(':');
        return (
          <div key={i} className="mt-3 mb-2 ml-4 pl-4 border-l-2 border-purple-300 break-inside-avoid flex items-center gap-2">
            <div className="w-2 h-2 bg-purple-500 rounded-full"></div>
            <p className="text-purple-900 font-semibold text-[15px]">
               <span className="underline decoration-purple-300 underline-offset-4">{title}:</span> 
               <span className="text-slate-700 ml-1">{rest.join(':')}</span>
            </p>
          </div>
        );
      }

      // Detection for Bullet Points - Infographic Style
      if (trimmed.startsWith('•') || trimmed.startsWith('*') || trimmed.startsWith('-')) {
         const text = trimmed.substring(1).trim();
         return (
            <div key={i} className="flex gap-3 ml-6 mb-3 items-start p-2 rounded-lg hover:bg-slate-50 transition-colors">
               <div className="mt-1 text-emerald-600 bg-emerald-50 rounded-full p-0.5 shrink-0">
                  <CheckCircle2 size={16} />
               </div>
               <p className="text-justify leading-relaxed text-slate-800 font-medium text-[15px]">{text}</p>
            </div>
         )
      }

      // Mission/Vision - High Impact Cards
      if (trimmed.startsWith('মিশন') || trimmed.startsWith('ভিশন')) {
          const isMission = trimmed.startsWith('মিশন');
          return (
             <div key={i} className={`mt-8 mb-4 p-4 rounded-xl border-l-4 shadow-sm break-inside-avoid ${
                 isMission 
                 ? 'bg-orange-50 border-orange-500 text-orange-900' 
                 : 'bg-emerald-50 border-emerald-500 text-emerald-900'
             }`}>
                <div className="flex items-center gap-2 mb-2">
                   {isMission ? <Target size={24} /> : <Shield size={24} />}
                   <h4 className="text-xl font-extrabold uppercase tracking-wide">
                     {trimmed}
                   </h4>
                </div>
             </div>
          )
      }

      // Empty lines
      if (trimmed === '') return <div key={i} className="h-2"></div>;

      // Standard Text - High Contrast for Print
      return (
        <p key={i} className="text-justify leading-loose text-slate-900 mb-2 font-serif text-[16px] tracking-wide">
          {line}
        </p>
      );
    });
  };

  const getPageTitleHeader = (page: RenderPage) => {
    const isContinuation = page.pageIndexInSection > 0;
    const titleText = isContinuation ? `${page.sectionTitle} (চলমান...)` : page.sectionTitle;

    if (page.sectionId === 'intro' && page.pageIndexInSection === 0) {
      return (
        <div className="text-center mb-10">
           <div className="inline-block relative">
              <div className="absolute inset-0 bg-slate-900 transform translate-x-1 translate-y-1 rounded-lg"></div>
              <span className="relative block bg-white text-slate-900 px-12 py-2 rounded-lg border-2 border-slate-900 font-black text-2xl uppercase tracking-[0.2em]">
                ভূমিকা
              </span>
           </div>
        </div>
      );
    } 

    if (page.sectionId === 'mission_vision') {
      return (
        <div className="relative mb-8 overflow-hidden rounded-xl bg-gradient-to-r from-orange-500 via-red-500 to-rose-500 p-6 text-white shadow-lg">
           <div className="absolute top-0 right-0 p-4 opacity-20 transform rotate-12">
              <Target size={100} />
           </div>
           <div className="relative z-10 flex items-center gap-4">
              <div className="bg-white/20 p-3 rounded-lg backdrop-blur-sm border border-white/30">
                <Sparkles size={32} className="text-white" />
              </div>
              <h3 className="text-3xl font-bold tracking-wide drop-shadow-md">
                 {titleText}
              </h3>
           </div>
        </div>
      );
    }

    // Default Chapter Style - Vibrant Gradient
    return (
      <div className="relative mb-8 overflow-hidden rounded-xl bg-gradient-to-r from-blue-700 via-indigo-600 to-violet-600 p-4 text-white shadow-md">
         <div className="absolute right-0 top-0 h-full w-1/3 bg-white/10 skew-x-12 transform origin-bottom-right"></div>

         <div className="relative z-10 flex items-center gap-4">
            {!isContinuation && (
              <div className="flex h-12 w-12 items-center justify-center rounded-full bg-white text-blue-700 font-black text-xl shadow-lg border-4 border-blue-200">
                #
              </div>
            )}
            <h3 className="text-xl font-bold tracking-wide text-white drop-shadow-sm">
               {titleText}
            </h3>
         </div>
      </div>
    );
  };

  return (
    <div className="space-y-8 pb-20">
      {/* Controls Bar */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 no-print bg-white p-4 rounded-xl shadow-sm border border-slate-200 sticky top-0 z-50">
        <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
          <FileText className="text-blue-600" /> গঠনতন্ত্র ও নীতিমালা
        </h2>
        <div className="flex flex-wrap gap-2 w-full md:w-auto">
          <button 
            onClick={() => setIsEditing(!isEditing)}
            className={`flex-1 md:flex-none px-4 py-2 rounded-lg font-medium text-sm border flex items-center gap-2 transition-colors ${isEditing ? 'bg-blue-600 text-white border-blue-700' : 'bg-slate-100 text-slate-700 border-slate-300 hover:bg-slate-200'}`}
          >
            {isEditing ? <Save size={16} /> : <Edit3 size={16} />} {isEditing ? 'সেভ করুন' : 'এডিট করুন'}
          </button>

          <div className="h-8 w-[1px] bg-slate-300 mx-1 hidden md:block"></div>

          <button 
            onClick={handleDownloadFullPDF}
            className="flex-1 md:flex-none px-6 py-2 bg-rose-600 text-white rounded-lg hover:bg-rose-700 font-medium flex items-center justify-center gap-2 text-sm shadow-sm shadow-rose-200"
          >
            <FileStack size={18} /> সম্পূর্ণ পিডিএফ ডাউনলোড
          </button>
        </div>
      </div>

      {isEditing && (
        <div className="bg-white p-6 rounded-xl shadow border border-slate-200 no-print animate-fade-in">
          <h3 className="font-semibold text-lg mb-4 text-slate-800 border-b pb-2">অনুচ্ছেদ পরিবর্তন করুন</h3>

          {/* AI Generation Box */}
          <div className="flex flex-col md:flex-row gap-2 mb-8 bg-purple-50 p-4 rounded-lg border border-purple-100">
            <div className="flex-1">
               <label className="text-xs font-bold text-purple-700 uppercase mb-1 block">AI এর মাধ্যমে লিখুন</label>
               <input 
                type="text" 
                value={aiPrompt}
                onChange={(e) => setAiPrompt(e.target.value)}
                placeholder="যেমন: নতুন সদস্য হওয়ার শর্তাবলী..."
                className="w-full p-2 border border-purple-200 rounded-lg focus:ring-2 focus:ring-purple-500 outline-none"
              />
            </div>
            <button 
              onClick={handleAiDraft}
              disabled={isGenerating}
              className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 flex items-center justify-center gap-2 disabled:opacity-50 mt-auto h-10"
            >
              <Sparkles size={18} /> {isGenerating ? 'লিখছে...' : 'তৈরি করুন'}
            </button>
          </div>

          <div className="space-y-6">
            {sections.map((section, idx) => (
              <div key={section.id} className="p-4 border border-slate-200 rounded-xl bg-slate-50 relative group hover:border-blue-300 transition-colors">
                <div className="absolute top-4 right-4 text-xs text-slate-400 font-mono bg-white px-2 py-1 rounded border">Section {idx + 1}</div>

                <div className="mb-3">
                  <label className="text-sm font-semibold text-slate-700 block mb-1">শিরোনাম (Title)</label>
                  <input 
                    value={section.title}
                    onChange={(e) => {
                      const newSections = [...sections];
                      newSections[idx].title = e.target.value;
                      onUpdateSections(newSections);
                    }}
                    className="w-full font-bold p-2 bg-white border border-slate-300 rounded focus:border-blue-500 outline-none"
                  />
                </div>

                <div>
                  <label className="text-sm font-semibold text-slate-700 block mb-1">মূল বিষয়বস্তু</label>
                  <textarea 
                    value={section.content}
                    onChange={(e) => {
                      const newSections = [...sections];
                      newSections[idx].content = e.target.value;
                      onUpdateSections(newSections);
                    }}
                    className="w-full h-64 p-3 bg-white resize-y border border-slate-300 rounded focus:border-blue-500 outline-none font-serif text-sm leading-relaxed"
                  />
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* RENDER PAGINATED PAGES */}
      <div className="flex flex-col gap-12 items-center bg-slate-100 p-4 md:p-8">
        {pages.map((page, index) => {
          return (
            <div key={page.id} className="relative flex flex-col items-center gap-2">

              {/* Visible Toolbar Above Each Page */}
              <div className="w-full max-w-[210mm] flex justify-between items-center px-1 no-print">
                 <span className="text-sm font-bold text-slate-500 bg-white px-3 py-1 rounded-full shadow-sm border border-slate-200">
                    পৃষ্ঠা {index + 1}: {page.sectionTitle} {page.pageIndexInSection > 0 ? `(অংশ ${page.pageIndexInSection + 1})` : ''}
                 </span>
                 <button 
                    onClick={() => downloadAsImage(page.id, `Page_${index+1}_${page.sectionTitle}`)}
                    className="flex items-center gap-2 px-4 py-2 bg-emerald-100 text-emerald-800 rounded-lg hover:bg-emerald-200 border border-emerald-200 font-semibold text-sm transition-all shadow-sm"
                    title="শুধুমাত্র এই পৃষ্ঠাটি ডাউনলোড করুন"
                 >
                   <ImageIcon size={16} /> ইমেজ ডাউনলোড
                 </button>
              </div>

              {/* A4 Page Container */}
              <div 
                id={page.id} 
                className="a4-paper flex flex-col relative shadow-2xl bg-white overflow-hidden"
                style={{ height: '297mm', maxHeight: '297mm' }} // Enforce height
              >

                {/* Decorative Border Frame inside A4 */}
                <div className="absolute inset-0 m-4 border-2 border-double border-slate-300 pointer-events-none z-20 rounded-sm"></div>
                <div className="absolute inset-0 m-5 border border-slate-100 pointer-events-none z-20 rounded-sm"></div>

                {/* Corner Accents */}
                <div className="absolute top-4 left-4 w-16 h-16 border-t-4 border-l-4 border-emerald-600 rounded-tl-lg z-20 opacity-30"></div>
                <div className="absolute top-4 right-4 w-16 h-16 border-t-4 border-r-4 border-orange-600 rounded-tr-lg z-20 opacity-30"></div>
                <div className="absolute bottom-4 left-4 w-16 h-16 border-b-4 border-l-4 border-blue-600 rounded-bl-lg z-20 opacity-30"></div>
                <div className="absolute bottom-4 right-4 w-16 h-16 border-b-4 border-r-4 border-purple-600 rounded-br-lg z-20 opacity-30"></div>

                {/* Watermark */}
                {logoUrl && (
                  <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-0 overflow-hidden">
                    <img 
                      src={logoUrl} 
                      alt="Watermark" 
                      className="w-[500px] opacity-[0.04] grayscale" 
                    />
                  </div>
                )}

                {/* Content Container */}
                <div className="relative z-30 h-full flex flex-col p-4">
                     {/* Header Section */}
                     <div className="w-full pb-4">
                        {/* Only show Full Document Header on First Page of Intro, or if desired on Page 1 */}
                        {page.sectionId === 'intro' && page.pageIndexInSection === 0 ? (
                           <DocumentHeader logoUrl={logoUrl} />
                        ) : (
                           // Mini Branding for other pages
                           <div className="flex items-center justify-between border-b-2 border-slate-100 pb-2 mb-6">
                              <div className="flex items-center gap-2 opacity-70">
                                 {logoUrl && <img src={logoUrl} className="w-8 h-8 object-contain" />}
                                 <div>
                                     <span className="text-xs font-black uppercase tracking-wider text-slate-700 block">আপন ফাউন্ডেশন</span>
                                     <span className="text-[9px] text-slate-500">বালিগাঁও, অষ্টগ্রাম</span>
                                 </div>
                              </div>
                              <span className="text-xs font-bold text-slate-400 bg-slate-50 px-2 py-1 rounded">পৃষ্ঠা {index + 1}</span>
                           </div>
                        )}

                        {/* Section Title Banner */}
                        {getPageTitleHeader(page)}
                     </div>

                     {/* Content Body */}
                     <div className="pl-2 pr-2 flex-1">
                        {renderStyledContent(page.contentLines, page.sectionId)}
                     </div>

                     {/* Footers */}
                     <div className="mt-auto pt-4">
                        {/* Footer for Introduction Page - Credits */}
                        {page.sectionId === 'intro' && page.pageIndexInSection === 0 && (
                            <div className="mt-4 pt-4 border-t-2 border-slate-800 flex justify-between items-end text-sm font-serif">
                               <div className="text-center">
                                   <p className="font-bold text-slate-800 text-lg mb-1">মুহাম্মদ উজ্জল মিয়া</p>
                                   <p className="text-slate-600">সংকলন ও সম্পাদনায়</p>
                               </div>
                               <div className="text-center">
                                   <p className="font-bold text-slate-800 text-lg mb-1">আব্দুল জিহাদ</p>
                                   <p className="text-slate-600">প্রধান উদ্যোক্তা ও প্রতিষ্ঠাতা উপদেষ্টা</p>
                               </div>
                            </div>
                        )}

                        {/* Approval Footer - ONLY on GLOBAL Last Page */}
                        {page.isGlobalLastPage && (
                           <div className="mt-6 pt-6 border-t-2 border-dotted border-slate-300 flex flex-col items-center justify-center">
                               <p className="text-sm font-semibold text-slate-500 mb-2 uppercase tracking-widest">অনুমোদনক্রমে</p>
                               <div className="inline-block px-12 py-4 border-2 border-slate-900 rounded-xl text-center bg-white shadow-lg">
                                  <h2 className="text-2xl font-black text-slate-900 uppercase tracking-widest font-serif">সাধারণ পরিষদ</h2>
                                  <p className="text-slate-600 font-bold mt-1">২০২৫ ইংরেজি</p>
                               </div>
                           </div>
                        )}

                        {/* Minimal Spacer for regular pages */}
                        {!page.isGlobalLastPage && !(page.sectionId === 'intro' && page.pageIndexInSection === 0) && (
                           <div className="h-6 w-full border-t border-slate-100 mt-2 flex justify-center">
                              <div className="w-1/3 h-1 bg-gradient-to-r from-transparent via-slate-200 to-transparent"></div>
                           </div> 
                        )}
                     </div>
                </div>

              </div>

              {/* Page Number Label (Outside Paper) */}
              <div className="text-center mt-2 text-slate-400 text-xs font-mono no-print">
                 Page {index + 1} of {pages.length} (Sec: {page.sectionId})
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { FileText, Sparkles, Image as ImageIcon, Edit3, Save, FileStack, CheckCircle2, Bookmark, Star, Shield, Target } from 'lucide-react';
import { generateConstitutionContent } from '../services/geminiService';
import { ConstitutionSection } from '../types';
import { DocumentHeader } from './DocumentHeader';
import { downloadAsImage, downloadMultipleElementsAsPDF } from '../utils/downloadUtils';

interface Props {
  logoUrl: string | null;
  sections: ConstitutionSection[];
  onUpdateSections: (sections: ConstitutionSection[]) => void;
}

// Type for a Renderable Page
interface RenderPage {
  id: string; // unique page id
  sectionId: string;
  sectionTitle: string;
  pageIndexInSection: number; // 0 for first page of section
  totalPagesInSection: number; // Will be calculated
  contentLines: string[];
  isGlobalLastPage: boolean;
}

// Adjusted height for fluffier, more visual content
const MAX_CONTENT_HEIGHT = 700; 

const estimateLineHeight = (line: string): number => {
  const trimmed = line.trim();
  if (!trimmed) return 24; 
  if (trimmed.startsWith('ধারা')) return 100; // Increased for Card style
  if (trimmed.startsWith('উপধারা')) return 60; 
  if (trimmed.startsWith('মিশন') || trimmed.startsWith('ভিশন')) return 90; 

  // Bullets and Paragraphs
  const charLength = trimmed.length;
  const lines = Math.ceil(charLength / 80); // Slightly less chars per line due to padding
  return lines * 32 + 16; // Increased line-height and margin
};

export const Constitution: React.FC<Props> = ({ logoUrl, sections, onUpdateSections }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [aiPrompt, setAiPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);

  const handleAiDraft = async () => {
    if (!aiPrompt) return;
    setIsGenerating(true);
    const draft = await generateConstitutionContent(aiPrompt);
    onUpdateSections([...sections, { id: Date.now().toString(), title: aiPrompt, content: draft }]);
    setAiPrompt('');
    setIsGenerating(false);
  };

  const handleDownloadFullPDF = () => {
    const pageIds = document.querySelectorAll('.a4-paper');
    const ids = Array.from(pageIds).map(el => el.id);
    downloadMultipleElementsAsPDF(ids, 'Apon_Foundation_Constitution_Full');
  };

  // --- PAGINATION LOGIC ---
  const pages = useMemo(() => {
    const generatedPages: RenderPage[] = [];

    sections.forEach((section) => {
      // PRE-PROCESSING: Separate credits from body for INTRO section
      let contentToPaginate = section.content;
      if (section.id === 'intro') {
         // Remove the credits part from the body text to prevent it from flowing to next page as text
         const splitMarker = 'সংকলন ও সম্পাদনায়:';
         if (contentToPaginate.includes(splitMarker)) {
            contentToPaginate = contentToPaginate.split(splitMarker)[0].trim();
         }
      }

      const rawLines = contentToPaginate.split('\n');
      let currentHeight = 0;
      let currentLines: string[] = [];
      let pageIndex = 0;

      // Temporary array to hold pages for this section to calculate totalPagesInSection later
      const sectionPages: RenderPage[] = [];

      // Intro page header adjustment (Intro has larger header)
      const maxH = section.id === 'intro' ? 550 : MAX_CONTENT_HEIGHT;

      rawLines.forEach((line) => {
        const h = estimateLineHeight(line);

        if (currentHeight + h > maxH && currentLines.length > 0) {
          sectionPages.push({
            id: `page-${section.id}-${pageIndex}`,
            sectionId: section.id,
            sectionTitle: section.title,
            pageIndexInSection: pageIndex,
            totalPagesInSection: 0, // Will update
            contentLines: currentLines,
            isGlobalLastPage: false 
          });

          currentLines = [];
          currentHeight = 0;
          pageIndex++;
        }

        currentLines.push(line);
        currentHeight += h;
      });

      if (currentLines.length > 0) {
        sectionPages.push({
          id: `page-${section.id}-${pageIndex}`,
          sectionId: section.id,
          sectionTitle: section.title,
          pageIndexInSection: pageIndex,
          totalPagesInSection: 0, 
          contentLines: currentLines,
          isGlobalLastPage: false
        });
      }

      // Update total pages for this section and add to main list
      const totalInSection = sectionPages.length;
      sectionPages.forEach(p => p.totalPagesInSection = totalInSection);
      generatedPages.push(...sectionPages);
    });

    return generatedPages.map((page, idx) => ({
      ...page,
      isGlobalLastPage: idx === generatedPages.length - 1
    }));

  }, [sections]);


  // Helper function to render text with specific formatting
  const renderStyledContent = (lines: string[], sectionId: string) => {
    // Note: We already stripped credits in pagination logic, so just render lines directly
    return lines.map((line, i) => {
      const trimmed = line.trim();

      // Detection for "ধারা" (Article) - Colorful Card Style
      if (trimmed.startsWith('ধারা')) {
        const [title, ...rest] = trimmed.split(':');
        return (
          <div key={i} className="mt-6 mb-4 relative break-inside-avoid">
            <div className="absolute left-0 top-0 bottom-0 w-1.5 bg-gradient-to-b from-blue-600 to-purple-600 rounded-l-lg"></div>
            <div className="bg-gradient-to-r from-blue-50 to-white p-4 rounded-r-lg shadow-sm border-t border-r border-b border-blue-100 flex items-center gap-3">
               <div className="bg-blue-600 text-white p-1.5 rounded-md shadow-md">
                 <Bookmark size={20} />
               </div>
               <div>
                  <span className="text-blue-900 font-extrabold text-lg mr-2">{title}:</span>
                  <span className="text-slate-800 font-bold text-lg">{rest.join(':')}</span>
               </div>
            </div>
          </div>
        );
      }

      // Detection for "উপধারা" (Sub-article) - Distinct Color
      if (trimmed.startsWith('উপধারা')) {
        const [title, ...rest] = trimmed.split(':');
        return (
          <div key={i} className="mt-3 mb-2 ml-4 pl-4 border-l-2 border-purple-300 break-inside-avoid flex items-center gap-2">
            <div className="w-2 h-2 bg-purple-500 rounded-full"></div>
            <p className="text-purple-900 font-semibold text-[15px]">
               <span className="underline decoration-purple-300 underline-offset-4">{title}:</span> 
               <span className="text-slate-700 ml-1">{rest.join(':')}</span>
            </p>
          </div>
        );
      }

      // Detection for Bullet Points - Infographic Style
      if (trimmed.startsWith('•') || trimmed.startsWith('*') || trimmed.startsWith('-')) {
         const text = trimmed.substring(1).trim();
         return (
            <div key={i} className="flex gap-3 ml-6 mb-3 items-start p-2 rounded-lg hover:bg-slate-50 transition-colors">
               <div className="mt-1 text-emerald-600 bg-emerald-50 rounded-full p-0.5 shrink-0">
                  <CheckCircle2 size={16} />
               </div>
               <p className="text-justify leading-relaxed text-slate-800 font-medium text-[15px]">{text}</p>
            </div>
         )
      }

      // Mission/Vision - High Impact Cards
      if (trimmed.startsWith('মিশন') || trimmed.startsWith('ভিশন')) {
          const isMission = trimmed.startsWith('মিশন');
          return (
             <div key={i} className={`mt-8 mb-4 p-4 rounded-xl border-l-4 shadow-sm break-inside-avoid ${
                 isMission 
                 ? 'bg-orange-50 border-orange-500 text-orange-900' 
                 : 'bg-emerald-50 border-emerald-500 text-emerald-900'
             }`}>
                <div className="flex items-center gap-2 mb-2">
                   {isMission ? <Target size={24} /> : <Shield size={24} />}
                   <h4 className="text-xl font-extrabold uppercase tracking-wide">
                     {trimmed}
                   </h4>
                </div>
             </div>
          )
      }

      // Empty lines
      if (trimmed === '') return <div key={i} className="h-2"></div>;

      // Standard Text - High Contrast for Print
      return (
        <p key={i} className="text-justify leading-loose text-slate-900 mb-2 font-serif text-[16px] tracking-wide">
          {line}
        </p>
      );
    });
  };

  const getPageTitleHeader = (page: RenderPage) => {
    const isContinuation = page.pageIndexInSection > 0;
    const titleText = isContinuation ? `${page.sectionTitle} (চলমান...)` : page.sectionTitle;

    if (page.sectionId === 'intro' && page.pageIndexInSection === 0) {
      return (
        <div className="text-center mb-10">
           <div className="inline-block relative">
              <div className="absolute inset-0 bg-slate-900 transform translate-x-1 translate-y-1 rounded-lg"></div>
              <span className="relative block bg-white text-slate-900 px-12 py-2 rounded-lg border-2 border-slate-900 font-black text-2xl uppercase tracking-[0.2em]">
                ভূমিকা
              </span>
           </div>
        </div>
      );
    } 

    if (page.sectionId === 'mission_vision') {
      return (
        <div className="relative mb-8 overflow-hidden rounded-xl bg-gradient-to-r from-orange-500 via-red-500 to-rose-500 p-6 text-white shadow-lg">
           <div className="absolute top-0 right-0 p-4 opacity-20 transform rotate-12">
              <Target size={100} />
           </div>
           <div className="relative z-10 flex items-center gap-4">
              <div className="bg-white/20 p-3 rounded-lg backdrop-blur-sm border border-white/30">
                <Sparkles size={32} className="text-white" />
              </div>
              <h3 className="text-3xl font-bold tracking-wide drop-shadow-md">
                 {titleText}
              </h3>
           </div>
        </div>
      );
    }

    // Default Chapter Style - Vibrant Gradient
    return (
      <div className="relative mb-8 overflow-hidden rounded-xl bg-gradient-to-r from-blue-700 via-indigo-600 to-violet-600 p-4 text-white shadow-md">
         <div className="absolute right-0 top-0 h-full w-1/3 bg-white/10 skew-x-12 transform origin-bottom-right"></div>

         <div className="relative z-10 flex items-center gap-4">
            {!isContinuation && (
              <div className="flex h-12 w-12 items-center justify-center rounded-full bg-white text-blue-700 font-black text-xl shadow-lg border-4 border-blue-200">
                #
              </div>
            )}
            <h3 className="text-xl font-bold tracking-wide text-white drop-shadow-sm">
               {titleText}
            </h3>
         </div>
      </div>
    );
  };

  return (
    <div className="space-y-8 pb-20">
      {/* Controls Bar */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 no-print bg-white p-4 rounded-xl shadow-sm border border-slate-200 sticky top-0 z-50">
        <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
          <FileText className="text-blue-600" /> গঠনতন্ত্র ও নীতিমালা
        </h2>
        <div className="flex flex-wrap gap-2 w-full md:w-auto">
          <button 
            onClick={() => setIsEditing(!isEditing)}
