import React, { useRef, useState } from 'react';
import { Target, Shield, BookOpen, Star, CheckCircle2, Crown, Download, FileDown, Loader2, Sparkles, Quote } from 'lucide-react';
import { ConstitutionSection } from '../types';
import { downloadMultipleElementsAsPDF } from '../utils/downloadUtils';

interface Props {
  logoUrl: string | null;
  sections: ConstitutionSection[];
}

export const ConstitutionInfographic: React.FC<Props> = ({ logoUrl, sections }) => {
  const [isDownloading, setIsDownloading] = useState(false);
  const [progress, setProgress] = useState('');

  const handleDownload = async () => {
    setIsDownloading(true);
    setProgress('প্রসেসিং হচ্ছে...');

    // Get all infographic slide IDs
    const slides = document.querySelectorAll('.infographic-slide');
    const ids = Array.from(slides).map(el => el.id);

    setTimeout(async () => {
        await downloadMultipleElementsAsPDF(ids, 'Apon_Foundation_Infographic_Guidelines', (current, total) => {
            setProgress(`PDF তৈরি হচ্ছে: ${current} / ${total}`);
        });
        setIsDownloading(false);
        setProgress('');
    }, 500);
  };

  // Helper to parse content into visual elements
  const renderContent = (content: string) => {
    const lines = content.split('\n');
    return lines.map((line, idx) => {
      const trimmed = line.trim();
      if (!trimmed) return <div key={idx} className="h-4" />;

      if (trimmed.startsWith('ধারা')) {
        const parts = trimmed.split(':');
        return (
          <div key={idx} className="mt-6 mb-3 bg-white/90 backdrop-blur-sm p-4 rounded-xl border-l-8 border-indigo-500 shadow-md transform hover:scale-[1.01] transition-transform">
             <h3 className="text-xl font-black text-indigo-900 flex items-center gap-2">
                <span className="bg-indigo-100 p-1 rounded text-indigo-600"><BookOpen size={20}/></span>
                {parts[0]}
             </h3>
             <p className="text-lg font-bold text-slate-700 mt-1 pl-9">{parts[1]}</p>
          </div>
        );
      }

      if (trimmed.startsWith('উপধারা')) {
        const parts = trimmed.split(':');
        return (
          <div key={idx} className="ml-8 mb-2 p-3 bg-indigo-50 rounded-lg border border-indigo-100 flex gap-3 items-start">
             <div className="mt-1 w-2 h-2 rounded-full bg-indigo-400 shrink-0"></div>
             <div>
                <span className="font-bold text-indigo-700">{parts[0]}:</span>
                <span className="text-slate-700 ml-2 font-medium">{parts[1]}</span>
             </div>
          </div>
        );
      }

      if (trimmed.startsWith('•') || trimmed.startsWith('*')) {
         return (
            <div key={idx} className="flex items-start gap-3 ml-4 mb-2 p-3 bg-white rounded-lg shadow-sm border-b-2 border-slate-100">
               <CheckCircle2 className="text-emerald-500 shrink-0 mt-0.5" size={20} />
               <p className="text-slate-800 font-medium text-lg leading-relaxed">{trimmed.substring(1)}</p>
            </div>
         );
      }

      if (trimmed.startsWith('মিশন') || trimmed.startsWith('ভিশন')) {
          const isMission = trimmed.startsWith('মিশন');
          return (
             <div key={idx} className={`mt-6 mb-4 p-6 rounded-2xl shadow-lg text-white relative overflow-hidden ${isMission ? 'bg-gradient-to-br from-orange-400 to-red-500' : 'bg-gradient-to-br from-emerald-400 to-teal-600'}`}>
                <div className="absolute top-0 right-0 p-4 opacity-20"><Sparkles size={60}/></div>
                <h2 className="text-3xl font-black uppercase tracking-wider mb-2 flex items-center gap-3">
                   {isMission ? <Target size={32} /> : <Shield size={32} />}
                   {trimmed}
                </h2>
             </div>
          );
      }

      return <p key={idx} className="mb-2 text-slate-700 leading-loose font-medium text-lg text-justify">{line}</p>;
    });
  };

  // Function to determine slide background based on index or content
  const getSlideStyle = (index: number, title: string) => {
     if (title.includes('পরিচয়') || title === 'প্রচ্ছদ') return 'bg-gradient-to-br from-slate-900 via-blue-900 to-slate-900';
     if (title.includes('মিশন')) return 'bg-gradient-to-br from-orange-50 to-orange-100';
     if (title.includes('সদস্য')) return 'bg-gradient-to-br from-blue-50 to-cyan-50';
     if (title.includes('অর্থনৈতিক')) return 'bg-gradient-to-br from-emerald-50 to-teal-50';
     return index % 2 === 0 ? 'bg-gradient-to-br from-white to-slate-50' : 'bg-gradient-to-br from-purple-50 to-pink-50';
  };

  return (
    <div className="pb-20">
       {/* Control Bar */}
       <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 sticky top-0 z-50 flex flex-col md:flex-row justify-between items-center gap-4 mb-8">
          <div>
            <h2 className="text-2xl font-black text-transparent bg-clip-text bg-gradient-to-r from-purple-600 to-pink-600 flex items-center gap-2">
               <Sparkles className="text-purple-500" /> গঠনতন্ত্র নীতিমালা (ইনফোগ্রাফিক)
            </h2>
            <p className="text-xs text-slate-500 mt-1">হাই-কোয়ালিটি ভিজ্যুয়াল প্রেজেন্টেশন মোড</p>
          </div>

          <div className="flex items-center gap-3">
             {isDownloading && <span className="text-sm font-bold text-purple-600 animate-pulse">{progress}</span>}
             <button 
               onClick={handleDownload}
               disabled={isDownloading}
               className="bg-gradient-to-r from-purple-600 to-pink-600 text-white px-6 py-2.5 rounded-full font-bold shadow-lg hover:shadow-xl hover:scale-105 transition-all flex items-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
             >
                {isDownloading ? <Loader2 size={20} className="animate-spin" /> : <FileDown size={20} />}
                PDF ডাউনলোড করুন
             </button>
          </div>
       </div>

       {/* Disclaimer */}
       <div className="mb-8 p-4 bg-blue-50 text-blue-800 rounded-lg border border-blue-200 text-center text-sm">
          <strong>নির্দেশনা:</strong> পিডিএফটি ডাউনলোড করার পর আপনার গুগল ড্রাইভে আপলোড করুন এবং সেখান থেকে লিংকটি শেয়ার করুন। সরাসরি ওয়েবসাইট থেকে এই ফাইলটি অনেক বড় হতে পারে।
       </div>

       {/* Infographic Container - Vertical Flow */}
       <div className="flex flex-col items-center gap-8">

          {sections.map((section, index) => {
             // Skip raw cover page text, we make a custom graphic cover
             if (section.id === 'cover_page') return (
                <div 
                   id={`infographic-${index}`} 
                   key={section.id}
                   className="infographic-slide w-full max-w-4xl aspect-[3/4] md:aspect-[16/9] relative overflow-hidden rounded-[2rem] shadow-2xl flex flex-col items-center justify-center text-center p-12 bg-gradient-to-br from-indigo-900 via-purple-900 to-slate-900 text-white"
                >
                   {/* Background Particles */}
                   <div className="absolute inset-0 opacity-30 bg-[url('https://www.transparenttextures.com/patterns/stardust.png')]"></div>
                   <div className="absolute top-0 right-0 w-96 h-96 bg-purple-500 rounded-full mix-blend-overlay filter blur-[100px] opacity-50"></div>
                   <div className="absolute bottom-0 left-0 w-96 h-96 bg-blue-500 rounded-full mix-blend-overlay filter blur-[100px] opacity-50"></div>

                   <div className="relative z-10 animate-fade-in-up">
                      <div className="w-32 h-32 mx-auto mb-8 bg-white/10 backdrop-blur-md rounded-full p-4 border border-white/20 shadow-[0_0_50px_rgba(255,255,255,0.3)]">
                         {logoUrl ? <img src={logoUrl} className="w-full h-full object-contain" /> : <Crown size={64} className="mx-auto mt-2 text-yellow-400" />}
                      </div>

                      <h1 className="text-6xl md:text-8xl font-black mb-4 tracking-tighter text-transparent bg-clip-text bg-gradient-to-r from-yellow-200 to-amber-500 filter drop-shadow-lg">
                         আপন ফাউন্ডেশন
                      </h1>
                      <div className="h-2 w-40 bg-gradient-to-r from-transparent via-white to-transparent mx-auto mb-6"></div>
                      <h2 className="text-3xl md:text-5xl font-bold font-serif text-white/90 mb-12">
                         গঠনতন্ত্র ও নীতিমালা
                      </h2>

                      <div className="inline-block bg-white/10 backdrop-blur-md px-8 py-4 rounded-xl border border-white/10">
                         <p className="text-sm uppercase tracking-[0.3em] text-blue-200 mb-1">স্থাপিত</p>
                         <p className="text-4xl font-black text-white">২০২৫</p>
                      </div>
                   </div>
                   <div className="absolute bottom-8 text-white/40 text-sm font-mono">অফিসিয়াল ইনফোগ্রাফিক সংস্করণ</div>
                </div>
             );

             return (
                <div 
                   id={`infographic-${index}`} 
                   key={section.id}
                   className={`infographic-slide w-full max-w-4xl min-h-[800px] relative overflow-hidden rounded-[2rem] shadow-xl p-8 md:p-16 flex flex-col ${getSlideStyle(index, section.title)}`}
                >
                   {/* Header of Slide */}
                   <div className="flex items-center gap-6 mb-10 border-b-4 border-black/5 pb-6">
                      <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-indigo-600 to-purple-600 flex items-center justify-center text-white shadow-lg rotate-3">
                         <span className="text-2xl font-black">#{index}</span>
                      </div>
                      <div>
                         <h2 className="text-4xl font-black text-slate-800">{section.title}</h2>
                         <div className="flex gap-2 mt-2">
                            <div className="h-1.5 w-12 bg-indigo-500 rounded-full"></div>
                            <div className="h-1.5 w-6 bg-purple-500 rounded-full"></div>
                            <div className="h-1.5 w-2 bg-pink-500 rounded-full"></div>
                         </div>
                      </div>
                   </div>

                   {/* Content Body */}
                   <div className="flex-1 relative z-10">
                      {renderContent(section.content)}
                   </div>

                   {/* Footer Decoration */}
                   <div className="absolute bottom-0 right-0 opacity-5 pointer-events-none">
                      <Quote size={200} />
                   </div>
                   <div className="mt-10 pt-6 border-t border-slate-200 flex justify-between items-center text-slate-400 text-xs font-bold uppercase tracking-widest">
                      <span>আপন ফাউন্ডেশন</span>
                      <span>বালিগাঁও, অষ্টগ্রাম</span>
                   </div>
                </div>
             );
          })}
       </div>
    </div>
  );
};

