import React, { useState } from 'react';
import { FileText, Sparkles, Edit3, Save, FileStack, CheckCircle2, Bookmark, Target, Shield, Loader2, Book, Quote } from 'lucide-react';
import { generateConstitutionContent } from '../services/geminiService';
import { ConstitutionSection } from '../types';
import { DocumentHeader } from './DocumentHeader';

interface Props {
  logoUrl: string | null;
  sections: ConstitutionSection[];
  onUpdateSections: (sections: ConstitutionSection[]) => void;
}

export const Constitution: React.FC<Props> = ({ logoUrl, sections, onUpdateSections }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [aiPrompt, setAiPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);

  // Download State
  const [isDownloading, setIsDownloading] = useState(false);
  const [downloadProgress, setDownloadProgress] = useState('');

  const handleAiDraft = async () => {
    if (!aiPrompt) return;
    setIsGenerating(true);
    const draft = await generateConstitutionContent(aiPrompt);
    onUpdateSections([...sections, { id: Date.now().toString(), title: aiPrompt, content: draft }]);
    setAiPrompt('');
    setIsGenerating(false);
  };

  const handleDownloadFullPDF = async () => {
    setIsDownloading(true);
    setDownloadProgress('প্রস্তুত হচ্ছে...');

    // Small delay to let UI render overlay
    setTimeout(async () => {
      try {
        const element = document.getElementById('constitution-full-doc');
        if (!element) {
             throw new Error("Element not found");
        }

        const html2canvas = (window as any).html2canvas;
        const { jsPDF } = (window as any).jspdf;

        if (!html2canvas || !jsPDF) {
            alert("লাইব্রেরি লোড হয়নি। পেজ রিফ্রেশ করুন।");
            setIsDownloading(false);
            return;
        }

        // Capture the entire continuous element
        // Reduced scale slightly to prevent browser memory crash on very long documents
        const canvas = await html2canvas(element, {
            scale: 1.5, 
            useCORS: true,
            backgroundColor: '#ffffff',
            logging: false
        });

        const imgData = canvas.toDataURL('image/jpeg', 0.85);
        const pdfWidth = 210; // Standard A4 Width in mm
        const pxWidth = canvas.width;
        const pxHeight = canvas.height;

        // Calculate height maintaining aspect ratio
        const pdfHeight = (pxHeight * pdfWidth) / pxWidth;

        // Create a PDF with custom dimensions (Single Long Page)
        const pdf = new jsPDF('p', 'mm', [pdfWidth, pdfHeight], true);

        pdf.addImage(imgData, 'JPEG', 0, 0, pdfWidth, pdfHeight, undefined, 'FAST');
        pdf.save('Apon_Foundation_Constitution_Full.pdf');

      } catch (err) {
        console.error("PDF generation failed:", err);
        alert("পিডিএফ তৈরি করতে সমস্যা হয়েছে। দয়া করে আবার চেষ্টা করুন।");
      } finally {
        setIsDownloading(false);
        setDownloadProgress('');
      }
    }, 500);
  };

  // Render content with styling
  const renderStyledContent = (content: string) => {
    const lines = content.split('\n');
    return lines.map((line, i) => {
      const trimmed = line.trim();

      // Detection for "ধারা" (Article) - Colorful Card Style
      if (trimmed.startsWith('ধারা')) {
        const [title, ...rest] = trimmed.split(':');
        return (
          <div key={i} className="mt-8 mb-4 relative">
            <div className="absolute left-0 top-0 bottom-0 w-1.5 bg-gradient-to-b from-blue-600 to-purple-600 rounded-l-lg"></div>
            <div className="bg-gradient-to-r from-blue-50 to-white p-5 rounded-r-lg shadow-sm border-t border-r border-b border-blue-100 flex items-start gap-3">
               <div className="bg-blue-600 text-white p-1.5 rounded-md shadow-md mt-1 shrink-0">
                 <Bookmark size={18} />
               </div>
               <div>
                  <span className="text-blue-900 font-extrabold text-xl mr-2 block md:inline">{title}:</span>
                  <span className="text-slate-800 font-bold text-lg leading-relaxed">{rest.join(':')}</span>
               </div>
            </div>
          </div>
        );
      }

      // Detection for "উপধারা" (Sub-article)
      if (trimmed.startsWith('উপধারা')) {
        const [title, ...rest] = trimmed.split(':');
        return (
          <div key={i} className="mt-3 mb-2 ml-4 pl-4 border-l-2 border-purple-300 flex items-start gap-2 bg-purple-50/50 p-2 rounded-r-lg">
            <div className="w-2 h-2 bg-purple-500 rounded-full mt-2 shrink-0"></div>
            <p className="text-purple-900 font-semibold text-[15px] leading-relaxed">
               <span className="underline decoration-purple-300 underline-offset-4 font-bold">{title}:</span> 
               <span className="text-slate-700 ml-2">{rest.join(':')}</span>
            </p>
          </div>
        );
      }

      // Detection for Bullet Points
      if (trimmed.startsWith('•') || trimmed.startsWith('*') || trimmed.startsWith('-')) {
         const text = trimmed.substring(1).trim();
         return (
            <div key={i} className="flex gap-3 ml-6 mb-3 items-start p-2 rounded-lg hover:bg-emerald-50/30 transition-colors">
               <div className="mt-1 text-emerald-600 bg-emerald-50 rounded-full p-0.5 shrink-0">
                  <CheckCircle2 size={16} />
               </div>
               <p className="text-justify leading-relaxed text-slate-800 font-medium text-[15px]">{text}</p>
            </div>
         )
      }

      // Mission/Vision
      if (trimmed.startsWith('মিশন') || trimmed.startsWith('ভিশন')) {
          const isMission = trimmed.startsWith('মিশন');
          return (
             <div key={i} className={`mt-8 mb-4 p-6 rounded-xl border-l-4 shadow-sm ${
                 isMission 
                 ? 'bg-orange-50 border-orange-500 text-orange-900' 
                 : 'bg-emerald-50 border-emerald-500 text-emerald-900'
             }`}>
                <div className="flex items-center gap-3 mb-3 border-b border-black/5 pb-2">
                   {isMission ? <Target size={28} /> : <Shield size={28} />}
                   <h4 className="text-2xl font-extrabold uppercase tracking-wide">
                     {trimmed}
                   </h4>
                </div>
             </div>
          )
      }

      // Empty lines
      if (trimmed === '') return <div key={i} className="h-4"></div>;

      // Standard Text
      return (
        <p key={i} className="text-justify leading-loose text-slate-800 mb-3 font-serif text-[17px] tracking-wide">
          {line}
        </p>
      );
    });
  };

  return (
    <div className="space-y-8 pb-20 relative">
      {/* Loading Overlay */}
      {isDownloading && (
        <div className="fixed inset-0 bg-black/80 z-[100] flex flex-col items-center justify-center text-white backdrop-blur-sm">
           <Loader2 size={64} className="animate-spin mb-4 text-emerald-400" />
           <h3 className="text-2xl font-bold mb-2">পিডিএফ তৈরি হচ্ছে...</h3>
           <p className="text-emerald-200 font-mono text-lg">{downloadProgress}</p>
           <p className="text-sm text-slate-400 mt-4 max-w-md text-center">অনুগ্রহ করে অপেক্ষা করুন। ফাইলটি একটি দীর্ঘ পেজ হিসেবে জেনারেট হচ্ছে।</p>
        </div>
      )}

      {/* Controls Bar */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-slate-200 sticky top-0 z-50">
        <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
          <FileText className="text-blue-600" /> গঠনতন্ত্র ও নীতিমালা
        </h2>
        <div className="flex flex-wrap gap-2 w-full md:w-auto">
          <button 
            onClick={() => setIsEditing(!isEditing)}
