import React, { useState } from 'react';
import { Target, Shield, BookOpen, CheckCircle2, Crown, FileDown, Loader2, Sparkles, Quote, Award } from 'lucide-react';
import { ConstitutionSection } from '../types';

interface Props {
  logoUrl: string | null;
  sections: ConstitutionSection[];
}

export const ConstitutionInfographic: React.FC<Props> = ({ logoUrl, sections }) => {
  const [isDownloading, setIsDownloading] = useState(false);
  const [progress, setProgress] = useState('');

  const handleDownload = async () => {
    setIsDownloading(true);
    setProgress('প্রসেসিং হচ্ছে...');

    setTimeout(async () => {
      try {
        const element = document.getElementById('infographic-continuous-view');
        if (!element) throw new Error("Element not found");

        const html2canvas = (window as any).html2canvas;
        const { jsPDF } = (window as any).jspdf;

        if (!html2canvas || !jsPDF) {
            alert("লাইব্রেরি লোড হয়নি। দয়া করে পেজ রিফ্রেশ করুন।");
            return;
        }

        // Capture the entire long element
        const canvas = await html2canvas(element, {
            scale: 1.5, // Slightly lower scale to prevent crash on very long images
            useCORS: true,
            backgroundColor: '#0f172a', // Match background color
            logging: false
        });

        const imgData = canvas.toDataURL('image/jpeg', 0.90);

        // Calculate dimensions based on the captured canvas
        const pdfWidth = 210; // Fixed width in mm (like A4 width)
        const pxWidth = canvas.width;
        const pxHeight = canvas.height;
        const pdfHeight = (pxHeight * pdfWidth) / pxWidth; // Calculate relative height

        // Create PDF with custom dimensions (One long page)
        const pdf = new jsPDF('p', 'mm', [pdfWidth, pdfHeight], true);

        pdf.addImage(imgData, 'JPEG', 0, 0, pdfWidth, pdfHeight, undefined, 'FAST');
        pdf.save('Apon_Foundation_Full_Infographic.pdf');

      } catch (err) {
        console.error("PDF generation failed:", err);
        alert("পিডিএফ তৈরি করতে সমস্যা হয়েছে। দয়া করে আবার চেষ্টা করুন।");
      } finally {
        setIsDownloading(false);
        setProgress('');
      }
    }, 1000);
  };

  // Helper to parse content into visual elements
  const renderContent = (content: string) => {
    const lines = content.split('\n');
    return lines.map((line, idx) => {
      const trimmed = line.trim();
      if (!trimmed) return <div key={idx} className="h-4" />;

      if (trimmed.startsWith('ধারা')) {
        const parts = trimmed.split(':');
        return (
          <div key={idx} className="mt-6 mb-3 bg-white/95 p-5 rounded-2xl border-l-8 border-indigo-600 shadow-lg">
             <h3 className="text-xl font-black text-indigo-900 flex items-center gap-2">
                <span className="bg-indigo-100 p-1.5 rounded-lg text-indigo-600"><BookOpen size={20}/></span>
                {parts[0]}
             </h3>
             <p className="text-lg font-bold text-slate-700 mt-2 pl-10 leading-relaxed">{parts[1]}</p>
          </div>
        );
      }

      if (trimmed.startsWith('উপধারা')) {
        const parts = trimmed.split(':');
        return (
          <div key={idx} className="ml-4 md:ml-10 mb-3 p-4 bg-indigo-50/80 rounded-xl border border-indigo-100 flex gap-3 items-start hover:bg-indigo-100 transition-colors">
             <div className="mt-1.5 w-2.5 h-2.5 rounded-full bg-indigo-500 shrink-0 shadow-sm"></div>
             <div>
                <span className="font-bold text-indigo-800 text-lg">{parts[0]}:</span>
                <span className="text-slate-700 ml-2 font-medium text-lg">{parts[1]}</span>
             </div>
          </div>
        );
      }

      if (trimmed.startsWith('•') || trimmed.startsWith('*')) {
         return (
            <div key={idx} className="flex items-start gap-4 ml-6 mb-3 p-4 bg-white/80 rounded-xl shadow-sm border-l-4 border-emerald-400">
               <CheckCircle2 className="text-emerald-600 shrink-0 mt-0.5" size={22} />
               <p className="text-slate-800 font-bold text-lg leading-relaxed">{trimmed.substring(1)}</p>
            </div>
         );
      }

      if (trimmed.startsWith('মিশন') || trimmed.startsWith('ভিশন')) {
          const isMission = trimmed.startsWith('মিশন');
          return (
             <div key={idx} className={`mt-8 mb-6 p-8 rounded-3xl shadow-xl text-white relative overflow-hidden ${isMission ? 'bg-gradient-to-br from-orange-500 to-red-600' : 'bg-gradient-to-br from-emerald-500 to-teal-700'}`}>
                <div className="absolute top-0 right-0 p-4 opacity-20"><Sparkles size={80}/></div>
                <h2 className="text-4xl font-black uppercase tracking-wider mb-4 flex items-center gap-4 border-b-2 border-white/30 pb-4">
                   {isMission ? <Target size={40} /> : <Shield size={40} />}
                   {trimmed}
                </h2>
             </div>
          );
      }

      return <p key={idx} className="mb-3 text-slate-800 leading-loose font-medium text-xl text-justify font-serif opacity-90">{line}</p>;
    });
  };

  return (
    <div className="pb-20 bg-slate-100 min-h-screen">
       {/* Control Bar */}
       <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 sticky top-0 z-50 flex flex-col md:flex-row justify-between items-center gap-4 mb-8 mx-4 mt-4">
          <div>
            <h2 className="text-2xl font-black text-transparent bg-clip-text bg-gradient-to-r from-purple-600 to-pink-600 flex items-center gap-2">
               <Sparkles className="text-purple-500" /> গঠনতন্ত্র নীতিমালা (একটানা)
            </h2>
            <p className="text-xs text-slate-500 mt-1">লং স্ক্রোল ভিউ • হাই-কোয়ালিটি প্রিন্ট</p>
          </div>

          <div className="flex items-center gap-3">
             {isDownloading && <span className="text-sm font-bold text-purple-600 animate-pulse">{progress}</span>}
             <button 
               onClick={handleDownload}
               disabled={isDownloading}
               className="bg-gradient-to-r from-purple-600 to-pink-600 text-white px-6 py-2.5 rounded-full font-bold shadow-lg hover:shadow-xl hover:scale-105 transition-all flex items-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
             >
                {isDownloading ? <Loader2 size={20} className="animate-spin" /> : <FileDown size={20} />}
                সম্পূর্ণ পিডিএফ ডাউনলোড
             </button>
          </div>
       </div>

       {/* --- CONTINUOUS INFOGRAPHIC CONTAINER --- */}
       <div className="flex justify-center p-2 md:p-8">

           <div 
             id="infographic-continuous-view" 
             className="w-full max-w-4xl bg-slate-900 relative shadow-2xl overflow-hidden rounded-[3rem]"
             style={{
                // A subtle mesh gradient background for the entire long strip
                background: `
                    radial-gradient(at 0% 0%, hsla(253,16%,7%,1) 0, transparent 50%), 
                    radial-gradient(at 50% 0%, hsla(225,39%,30%,1) 0, transparent 50%), 
                    radial-gradient(at 100% 0%, hsla(339,49%,30%,1) 0, transparent 50%),
                    linear-gradient(to bottom, #0f172a, #1e1b4b, #0f172a)
                `
             }}
           >
              {/* --- COVER SECTION --- */}
              <div className="relative pt-24 pb-20 px-8 md:px-16 text-center border-b-8 border-amber-500/30">
                  {/* Decorative Elements */}
                  <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none">
                      <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-purple-600/20 rounded-full blur-[100px]"></div>
                      <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-blue-600/20 rounded-full blur-[100px]"></div>
                  </div>

                  {/* Bismillah */}
                  <div className="relative z-10 mb-12">
                      <p className="text-3xl md:text-5xl font-serif tracking-widest text-amber-400 drop-shadow-md">
                        بِسْمِ ٱللَّٰهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ
                      </p>
                  </div>

                  {/* Logo */}
                  <div className="relative z-10 mb-10 flex justify-center">
                      <div className="w-64 h-64 bg-white/95 rounded-full p-8 border-[6px] border-amber-400/50 shadow-[0_0_60px_rgba(251,191,36,0.3)] flex items-center justify-center">
                          {logoUrl ? (
                            <img src={logoUrl} className="w-full h-full object-contain drop-shadow-lg" alt="Foundation Logo" />
                          ) : (
                            <Crown size={100} className="text-amber-500" />
                          )}
                      </div>
                  </div>

                  {/* Title */}
                  <div className="relative z-10 w-full mb-10">
                      <h1 className="text-6xl md:text-8xl font-black mb-4 leading-tight tracking-tight text-amber-400 drop-shadow-xl" 
                          style={{ textShadow: '0 4px 0px rgba(0,0,0,0.5)' }}>
                          আপন ফাউন্ডেশন
                      </h1>
                      <div className="inline-block mt-4 bg-gradient-to-r from-amber-500 to-orange-600 px-12 py-4 rounded-full shadow-lg transform -rotate-1">
                          <h2 className="text-3xl md:text-5xl font-bold text-white tracking-wide font-serif">
                              গঠনতন্ত্র ও নীতিমালা
                          </h2>
                      </div>
                  </div>

                  {/* Footer Info of Cover */}
                  <div className="relative z-10 flex flex-col items-center gap-4 mt-16">
                      <div className="flex items-center gap-4 bg-white/10 px-8 py-3 rounded-full border border-white/20 backdrop-blur-sm">
                          <span className="text-emerald-300 font-bold tracking-widest uppercase">স্থাপিত: ২০২৫</span>
                          <span className="w-2 h-2 bg-amber-400 rounded-full"></span>
                          <span className="text-emerald-300 font-bold tracking-widest uppercase">রেজি: প্রক্রিয়াধীন</span>
                      </div>
                      <p className="text-amber-200/60 text-sm font-mono tracking-[0.5em] uppercase">
                          বালিগাঁও • অষ্টগ্রাম • কিশোরগঞ্জ
