              </div>

              {/* --- CONTENT SECTIONS --- */}
              <div className="px-6 md:px-12 py-12 relative z-10">
                 {sections.map((section, index) => {
                    if (section.id === 'cover_page') return null;

                    return (
                       <div key={section.id} className="mb-20 last:mb-0">
                          {/* Section Header Card */}
                          <div className="sticky top-0 z-20 mb-8 transform -rotate-1">
                              <div className="bg-gradient-to-r from-indigo-600 via-purple-600 to-pink-600 p-6 rounded-2xl shadow-xl border-2 border-white/20 flex items-center gap-6">
