  .blogger-app-root h2 { margin: 0; }
</style>

<!-- App Container -->
<div id="root" class="blogger-app-root">লোডিং হচ্ছে... দয়া করে অপেক্ষা করুন।</div>

<!-- REACT CODE STARTS HERE -->
<script type="text/babel">
  const { useState, useEffect } = React;

  // Lucide Icons Integration
  const ShieldCheck = () => <i data-lucide="shield-check" style={{width: 32, height: 32}}></i>;
  const UserCheck = () => <i data-lucide="user-check" style={{width: 32, height: 32}}></i>;
  const Users = () => <i data-lucide="users" style={{width: 32, height: 32}}></i>;
  const ArrowDown = () => <i data-lucide="arrow-down" style={{width: 24, height: 24}}></i>;
  const ArrowUp = () => <i data-lucide="arrow-up" style={{width: 24, height: 24}}></i>;

  // --- Organization Chart Component ---
  const OrganizationChart = () => {
    useEffect(() => {
      if (window.lucide) window.lucide.createIcons();
    }, []);

    return (
      <div className="w-full p-4 md:p-8 bg-white rounded-xl shadow-sm border border-slate-200">
        <h2 className="text-2xl font-bold text-slate-800 mb-8 text-center border-b pb-4">সাংগঠনিক কাঠামো</h2>

        <div className="relative flex flex-col items-center gap-8 max-w-4xl mx-auto">

          {/* Top Tier */}
          <div className="w-full md:w-2/3 bg-emerald-50 border border-emerald-200 p-6 rounded-xl text-center shadow-md">
            <div className="flex justify-center text-emerald-600 mb-2"><ShieldCheck /></div>
            <h3 className="text-xl font-bold text-emerald-900">উপদেষ্টা পরিষদ</h3>
            <p className="text-emerald-700 text-sm mt-2">দিকনির্দেশনা ও পরামর্শ প্রদানকারী</p>
          </div>

          {/* Connector */}
          <div className="flex flex-col items-center text-slate-400">
             <span className="text-xs mb-1">পরামর্শ</span>
             <ArrowDown />
          </div>

          {/* Middle Tier */}
          <div className="w-full md:w-2/3 bg-blue-50 border border-blue-200 p-6 rounded-xl text-center shadow-md">
            <div className="flex justify-center text-blue-600 mb-2"><UserCheck /></div>
            <h3 className="text-xl font-bold text-blue-900">নির্বাহী পরিষদ</h3>
            <p className="text-blue-700 text-sm mt-2">কার্যক্রম পরিচালনা ও সিদ্ধান্ত গ্রহণ</p>
          </div>

          {/* Connector */}
          <div className="flex flex-col items-center text-slate-400">
             <ArrowUp />
             <span className="text-xs mt-1">ভোট/নির্বাচন</span>
          </div>

          {/* Bottom Tier */}
          <div className="w-full md:w-2/3 bg-slate-50 border border-slate-200 p-6 rounded-xl text-center shadow-md">
            <div className="flex justify-center text-slate-600 mb-2"><Users /></div>
            <h3 className="text-xl font-bold text-slate-900">সাধারণ পরিষদ</h3>
            <p className="text-slate-700 text-sm mt-2">সকল সদস্যদের সমন্বয়ে গঠিত</p>
          </div>

        </div>
      </div>
    );
  };

  // --- Main App Logic ---
  const App = () => {
    return (
      <div className="min-h-screen">
        <div className="text-center mb-6">
           <h1 className="text-3xl font-bold text-blue-700">আপন ফাউন্ডেশন</h1>
           <p className="text-slate-500">অফিসিয়াল ড্যাশবোর্ড</p>
        </div>
        <OrganizationChart />
      </div>
    );
  };

  // Render to Blogger Div
  const root = ReactDOM.createRoot(document.getElementById('root'));
  root.render(<App />);
</script>
```

#### ধাপ ৩: পেজ সেভ এবং চেক করুন
1. **Publish** বা **Update** বাটনে ক্লিক করুন।
2. পেজটি ভিউ (View) করে দেখুন।

---

### জরুরি সতর্কবার্তা (অবশ্যই পড়বেন)

ব্লগারে এভাবে অ্যাপ বানালে কিছু সীমাবদ্ধতা থাকে:

১. **ডাটা সেভ হবে না:** বর্তমানে অ্যাপটি যেভাবে বানানো, তাতে আপনি যদি একজন সদস্যের নাম যোগ করেন, সেটা শুধু **আপনার ফোনেই** সেভ থাকবে (LocalStorage)। অন্য কেউ ওয়েবসাইট ভিজিট করলে সেই নাম দেখতে পাবে না।
   - *সমাধান:* আপনাকে গুগল শিট (Google Sheet) বা ফায়ারবেস (Firebase) ডাটাবেস হিসেবে কানেক্ট করতে হবে।

