          if (json.members) setMembers(json.members);
          if (json.transactions) setTransactions(json.transactions);
          if (json.constitutionSections) setConstitutionSections(json.constitutionSections);
          setImportStatus({ msg: 'সফলভাবে ডাটা রিস্টোর করা হয়েছে!', type: 'success' });
        } else {
          setImportStatus({ msg: 'ভুল ফাইল ফরম্যাট! সঠিক ব্যাকআপ ফাইল নির্বাচন করুন।', type: 'error' });
        }
      } catch (error) {
        setImportStatus({ msg: 'ফাইল রিড করতে সমস্যা হয়েছে।', type: 'error' });
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const NavItem = ({ view, icon: Icon, label }: { view: typeof activeView, icon: any, label: string }) => (
    <button
      onClick={() => { setActiveView(view); setIsMobileMenuOpen(false); }}
      className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
        activeView === view 
          ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' 
          : 'text-slate-600 hover:bg-white hover:shadow'
      }`}
    >
      <Icon size={20} />
      <span className="font-medium text-sm">{label}</span>
    </button>
  );

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row font-sans text-slate-700">

      {/* Sidebar */}
      <aside className={`fixed md:sticky top-0 z-50 h-screen w-64 bg-white border-r border-slate-200 p-4 flex flex-col transition-transform duration-300 ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'} overflow-y-auto custom-scrollbar`}>
        <div className="flex items-center gap-3 mb-6 px-2">
          <div className="w-10 h-10 rounded-lg bg-blue-600 flex items-center justify-center text-white overflow-hidden relative shadow-md shrink-0">
            {logo ? <img src={logo} className="w-full h-full object-cover" /> : <Upload size={20} />}
            {!logo && <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleLogoUpload} accept="image/*" />}
          </div>
          <div>
             <h1 className="font-bold text-slate-800 leading-tight">আপন ফাউন্ডেশন</h1>
             <p className="text-[10px] text-slate-500">ম্যানেজমেন্ট সিস্টেম</p>
          </div>
        </div>

        <nav className="space-y-1 flex-1">
          <NavItem view="DASHBOARD" icon={LayoutDashboard} label="ড্যাশবোর্ড" />
          <NavItem view="MEMBERS" icon={Users} label="সদস্য তালিকা" />
          <NavItem view="IDCARD" icon={Users} label="আইডি কার্ড" />
          <NavItem view="FORM" icon={FileText} label="ভর্তি ফরম" />
          <NavItem view="CONSTITUTION" icon={BookOpen} label="গঠনতন্ত্র (ডক)" />
          <NavItem view="CONSTITUTION_INFOGRAPHIC" icon={BookOpen} label="গঠনতন্ত্র (ইনফো)" />
          <NavItem view="NOTICE" icon={Bell} label="নোটিশ বোর্ড" />
          <NavItem view="FINANCE" icon={Wallet} label="আর্থিক হিসাব" />
          <NavItem view="DOCUMENTS" icon={FileText} label="ডকুমেন্টস" />
          <NavItem view="REPORTS" icon={PieChart} label="রিপোর্টস" />
          <NavItem view="BACKUP" icon={Save} label="ডাটা ও সেটিংস" />
        </nav>

        {/* PWA Install Button & Copy Link Button Area */}
        <div className="mt-4 px-2 space-y-2">
          {deferredPrompt && (
              <button
                onClick={handleInstallClick}
                className="w-full flex items-center justify-center gap-2 bg-gradient-to-r from-emerald-600 to-teal-600 text-white py-2.5 px-3 rounded-xl shadow-lg hover:shadow-xl transition-all font-bold text-sm animate-pulse"
              >
                <Smartphone size={18} /> অ্যাপ ইনস্টল করুন
              </button>
          )}

          <button 
            onClick={handleCopyLink}
            className={`w-full flex items-center justify-center gap-2 py-2.5 px-3 rounded-xl shadow-sm border transition-all font-bold text-sm ${
              linkCopied 
                ? 'bg-green-50 border-green-200 text-green-700' 
                : 'bg-white border-slate-200 text-slate-700 hover:bg-slate-50'
            }`}
          >
            {linkCopied ? <CheckCircle size={18} /> : <LinkIcon size={18} />} 
            {linkCopied ? 'লিংক কপি হয়েছে!' : 'লিংক শেয়ার করুন'}
          </button>
        </div>

        <div className="mt-4 p-4 bg-gradient-to-br from-blue-50 to-indigo-50 rounded-xl border border-blue-100 shrink-0">
          <p className="text-xs text-blue-800 font-semibold mb-1">সদস্য সংখ্যা</p>
          <p className="text-2xl font-bold text-blue-900">{members.length}</p>
        </div>
      </aside>

      {/* Mobile Header */}
      <div className="md:hidden bg-white p-4 flex justify-between items-center shadow-sm sticky top-0 z-40">
        <span className="font-bold text-slate-700">আপন ফাউন্ডেশন</span>
        <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
           {isMobileMenuOpen ? <X className="text-slate-600" /> : <Menu className="text-slate-600" />}
        </button>
      </div>

      {/* Main Content */}
      <main className="flex-1 p-4 md:p-8 overflow-y-auto max-h-screen">
        <div className="max-w-6xl mx-auto space-y-8">

          {activeView === 'DASHBOARD' && (
            <div className="animate-fade-in space-y-8">
              <header>
                <h1 className="text-3xl font-bold text-slate-800 mb-2">স্বাগতম!</h1>
                <p className="text-slate-600">এক নজরে ফাউন্ডেশনের সাংগঠনিক কাঠামো।</p>
              </header>
              <OrganizationChart />
            </div>
          )}

          {activeView === 'CONSTITUTION' && (
            <div className="animate-fade-in">
              <Constitution 
                logoUrl={logo} 
                sections={constitutionSections}
                onUpdateSections={setConstitutionSections}
              />
            </div>
          )}

          {activeView === 'CONSTITUTION_INFOGRAPHIC' && (
            <div className="animate-fade-in">
              <ConstitutionInfographic 
                logoUrl={logo} 
                sections={constitutionSections}
              />
            </div>
          )}

          {activeView === 'NOTICE' && (
            <div className="animate-fade-in">
              <header className="mb-6">
                <h1 className="text-3xl font-bold text-slate-800 mb-2">নোটিশ বোর্ড</h1>
                <p className="text-slate-600">আনুষ্ঠানিক নোটিশ তৈরি করুন এবং সদস্যদের কাছে পাঠান।</p>
              </header>
              <NoticeBoard members={members} logoUrl={logo} />
            </div>
          )}

          {activeView === 'MEMBERS' && (
            <div className="animate-fade-in">
               <MemberDirectory 
                 members={members} 
                 onAddMember={(m) => setMembers([...members, m])}
                 onUpdateMember={(updatedMember) => setMembers(members.map(m => m.id === updatedMember.id ? updatedMember : m))}
                 onDeleteMember={(id) => setMembers(members.filter(m => m.id !== id))}
                 logoUrl={logo}
               />
            </div>
          )}

          {activeView === 'IDCARD' && (
            <div className="animate-fade-in">
               <header className="mb-6">
                <h1 className="text-3xl font-bold text-slate-800 mb-2">আইডি কার্ড জেনারেটর</h1>
                <p className="text-slate-600">সদস্যদের জন্য প্রফেশনাল আইডি কার্ড তৈরি করুন।</p>
              </header>
              <IDCardGenerator members={members} logoUrl={logo} />
            </div>
          )}

          {activeView === 'FORM' && (
            <div className="animate-fade-in">
               <MemberForm logoUrl={logo} />
            </div>
          )}

          {activeView === 'DOCUMENTS' && (
            <div className="animate-fade-in">
               <header className="mb-6">
                <h1 className="text-3xl font-bold text-slate-800 mb-2">অফিসিয়াল ডকুমেন্টস</h1>
                <p className="text-slate-600">প্যাড, রসিদ এবং ভাউচার তৈরি করুন।</p>
              </header>
               <DocumentsGenerator logoUrl={logo} />
            </div>
          )}

          {activeView === 'FINANCE' && (
            <div className="animate-fade-in">
              <FinanceManager 
                transactions={transactions} 
                members={members}
                onAddTransaction={(t) => setTransactions([...transactions, t])}
                logoUrl={logo}
              />
            </div>
          )}

          {activeView === 'REPORTS' && (
            <div className="animate-fade-in">
               <header className="mb-6">
                <h1 className="text-3xl font-bold text-slate-800 mb-2">ইনফোগ্রাফিক রিপোর্ট</h1>
                <p className="text-slate-600">বিভিন্ন কার্যক্রমের রিপোর্ট তৈরি করুন এবং সোশ্যাল মিডিয়ায় শেয়ার করুন।</p>
              </header>
              <ActivityReports transactions={transactions} logoUrl={logo} />
            </div>
          )}

          {activeView === 'BACKUP' && (
            <div className="animate-fade-in">
              <div className="bg-white rounded-2xl shadow-lg border border-indigo-100 p-8 max-w-2xl mx-auto">
                <h2 className="text-2xl font-bold text-indigo-900 mb-6 flex items-center gap-2">
                  <Database className="text-blue-600" /> ডাটা ম্যানেজমেন্ট
                </h2>

                <div className="space-y-6">

                  {/* Google Sheet Sync Section */}
                  <div className="bg-gradient-to-r from-green-50 to-emerald-50 p-6 rounded-xl border border-green-200 shadow-sm relative overflow-hidden">
                     <div className="absolute top-0 right-0 p-4 opacity-10">
                        <img src="https://upload.wikimedia.org/wikipedia/commons/3/30/Google_Sheets_logo_%282014-2020%29.svg" className="w-16 h-16" />
                     </div>

                     <h3 className="font-bold text-lg text-green-800 mb-2 flex items-center gap-2">
                       <RefreshCw size={20} className={isSyncing ? "animate-spin" : ""} /> গুগল শিট থেকে ডাটা আনুন
                     </h3>
                     <p className="text-sm text-slate-600 mb-4">
                        আপনার গুগল শিটের <b>"Publish to Web"</b> লিংকটি (CSV ফরম্যাটে) নিচে পেস্ট করুন। অ্যাপটি অটোমেটিক সেখান থেকে সদস্যদের তথ্য নিয়ে আসবে।
                     </p>

                     <div className="flex gap-2">
                        <input 
                           type="text" 
                           placeholder="https://docs.google.com/spreadsheets/d/e/.../pub?output=csv"
                           value={sheetUrl}
                           onChange={(e) => setSheetUrl(e.target.value)}
                           className="flex-1 p-2 border border-green-300 rounded-lg text-sm focus:ring-2 focus:ring-green-500 outline-none bg-white"
                        />
                        <button 
                           onClick={handleSheetSync}
                           disabled={isSyncing}
                           className="bg-green-600 text-white px-4 py-2 rounded-lg font-bold shadow hover:bg-green-700 transition-colors disabled:opacity-50"
                        >
                           {isSyncing ? 'লোড হচ্ছে...' : 'Sync'}
                        </button>
                     </div>
                     <p className="text-[10px] text-slate-500 mt-2">
                        কলামের সিরিয়াল: নাম, মোবাইল, পরিষদ (Advisory/Executive/General), পদবী, NID, ঠিকানা, রক্তের গ্রুপ
                     </p>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {/* Export Section */}
                    <div className="bg-indigo-50 p-6 rounded-xl border border-indigo-200">
                        <h3 className="font-bold text-lg text-indigo-800 mb-2 flex items-center gap-2">
                        <DownloadCloud size={20} /> ব্যাকআপ ডাউনলোড করুন
                        </h3>
                        <p className="text-xs text-slate-600 mb-4">
                        মোবাইল ফরম্যাট দেওয়ার আগে ব্যাকআপ ফাইলটি সেভ করে রাখুন।
                        </p>
                        <button 
                        onClick={handleExportData}
                        className="bg-blue-600 text-white px-4 py-2 rounded-lg font-bold shadow hover:bg-blue-700 transition-colors w-full text-sm"
                        >
                        ডাউনলোড JSON
                        </button>
                    </div>

                    {/* Import Section */}
                    <div className="bg-purple-50 p-6 rounded-xl border border-purple-200">
                        <h3 className="font-bold text-lg text-purple-800 mb-2 flex items-center gap-2">
                        <UploadCloud size={20} /> ব্যাকআপ রিস্টোর করুন
                        </h3>
                        <p className="text-xs text-slate-600 mb-4">
                        আপনার সেভ করা ব্যাকআপ JSON ফাইলটি এখানে আপলোড করুন।
                        </p>

                        <input 
                        type="file" 
                        ref={fileInputRef}
                        onChange={handleImportData}
                        accept=".json"
                        className="hidden"
                        />

                        <button 
                        onClick={() => fileInputRef.current?.click()}
                        className="bg-purple-600 text-white px-4 py-2 rounded-lg font-bold shadow hover:bg-purple-700 transition-colors w-full text-sm"
                        >
                        আপলোড ফাইল
                        </button>
                    </div>
                  </div>

                  {importStatus && (
                    <div className={`p-3 rounded-lg flex items-center gap-2 ${importStatus.type === 'success' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
                    {importStatus.type === 'success' ? <CheckCircle size={18} /> : <AlertTriangle size={18} />}
                    <span className="font-medium text-sm">{importStatus.msg}</span>
                    </div>
                  )}

                </div>
              </div>
            </div>
          )}

        </div>
      </main>

      {/* Overlay for mobile menu */}
      {isMobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-black/20 z-40 md:hidden"
          onClick={() => setIsMobileMenuOpen(false)}
        />
      )}
    </div>
  );
}

export default App;
